{"command":"mkdir -p /tmp/rev/py && cat > /tmp/rev/py/pqmeta.py <<'EOF'
import struct, sys, json

class R:
    def __init__(self, b, pos=0):
        self.b=b; self.pos=pos
    def byte(self):
        v=self.b[self.pos]; self.pos+=1; return v
    def varint(self):
        r=0; sh=0
        while True:
            x=self.byte(); r|=(x&0x7f)<<sh; sh+=7
            if not x&0x80: return r
    def zig(self):
        n=self.varint(); return (n>>1) ^ -(n&1)
    def binary(self):
        n=self.varint(); v=self.b[self.pos:self.pos+n]; self.pos+=n; return v

def read_struct(r):
    # returns dict field_id -> value (raw), with type tags
    out={}
    last=0
    while True:
        h=r.byte()
        t=h&0x0f
        if t==0: return out
        d=h>>4
        if d==0:
            fid=r.zig()  # i16 zigzag
        else:
            fid=last+d
        last=fid
        out[fid]=read_val(r,t)

def read_val(r,t):
    if t==1: return True
    if t==2: return False
    if t==3: return struct.unpack('b',bytes([r.byte()]))[0]
    if t==4 or t==5 or t==6: return r.zig()
    if t==7:
        v=struct.unpack('<d', r.b[r.pos:r.pos+8])[0]; r.pos+=8; return v
    if t==8: return r.binary()
    if t==9 or t==10:
        h=r.byte(); n=h>>4; et=h&0x0f
        if n==15: n=r.varint()
        return [read_val(r,et) for _ in range(n)]
    if t==11:
        h=r.byte(); n=h>>4; et=h&0x0f  # actually map: size varint then kv types byte
        raise Exception('map unsupported')
    if t==12: return read_struct(r)
    raise Exception('bad type %d'%t)

def parse(path):
    b=open(path,'rb').read()
    assert b[-4:]==b'PAR1', b[-4:]
    n=struct.unpack('<I', b[-8:-4])[0]
    meta=b[-8-n:-8]
    r=R(meta)
    fm=read_struct(r)
    return fm, len(b)

TYPES=['BOOLEAN','INT32','INT64','INT96','FLOAT','DOUBLE','BYTE_ARRAY','FIXED_LEN_BYTE_ARRAY']
CONV=['UTF8','MAP','MAP_KEY_VALUE','LIST','ENUM','DECIMAL','DATE','TIME_MILLIS','TIME_MICROS','TIMESTAMP_MILLIS','TIMESTAMP_MICROS','UINT_8','UINT_16','UINT_32','UINT_64','INT_8','INT_16','INT_32','INT_64','JSON','BSON','INTERVAL']
REP=['REQUIRED','OPTIONAL','REPEATED']
ENC=['PLAIN','GROUP_VAR_INT','PLAIN_DICTIONARY','RLE','BIT_PACKED','DELTA_BINARY_PACKED','DELTA_LENGTH_BYTE_ARRAY','DELTA_BYTE_ARRAY','RLE_DICTIONARY','BYTE_STREAM_SPLIT']
CODEC=['UNCOMPRESSED','SNAPPY','GZIP','LZO','BROTLI','LZ4','ZSTD','LZ4_RAW']

def schema_elems(fm):
    out=[]
    for s in fm.get(2,[]):
        e={'type':TYPES[s[1]] if 1 in s else None,'type_length':s.get(2),'rep':REP[s[3]] if 3 in s else None,'name':s[4].decode(),'num_children':s.get(5),'converted':CONV[s[6]] if 6 in s else None,'scale':s.get(7),'precision':s.get(8),'field_id':s.get(9),'logical':s.get(10)}
        out.append(e)
    return out

def dump(path):
    fm,size=parse(path)
    print('file size',size)
    print('version',fm.get(1),'num_rows',fm.get(3),'created_by',fm.get(6))
    for e in schema_elems(fm): print('  ',e)
    for i,rg in enumerate(fm.get(4,[])):
        print('RG',i,'rows',rg.get(2),'total_byte_size',rg.get(3),'file_offset',rg.get(5),'total_compressed',rg.get(6),'ordinal',rg.get(7))
        for cc in rg.get(1,[]):
            md=cc.get(3,{})
            st=md.get(12)
            stats=None
            if st is not None:
                stats={'max':st.get(1),'min':st.get(2),'null_count':st.get(3),'distinct':st.get(4),'max_value':st.get(5),'min_value':st.get(6),'is_max_exact':st.get(7),'is_min_exact':st.get(8)}
            print('   col', [p.decode() for p in md.get(3,[])], TYPES[md[1]], [ENC[e] for e in md.get(2,[])], CODEC[md.get(4)], 'nvals',md.get(5),'unc',md.get(6),'comp',md.get(7), 'dict_off',md.get(11),'data_off',md.get(9),'idx_off',md.get(10), 'stats',stats, 'enc_stats', md.get(13))
    kv=fm.get(5)
    if kv: print('kv', [(k.get(1), (k.get(2) or b'')[:80]) for k in kv])
    print('col_orders', fm.get(7))

if __name__=='__main__':
    dump(sys.argv[1])
EOF
