//! Minimal Thrift compact-protocol reader.

use std::fmt;

#[derive(Debug, Clone)]
pub struct ThriftError(pub String);

impl fmt::Display for ThriftError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

pub type TResult<T> = Result<T, ThriftError>;

fn err<T>(msg: &str) -> TResult<T> {
    Err(ThriftError(msg.to_string()))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TType {
    Stop,
    BoolTrue,
    BoolFalse,
    Byte,
    I16,
    I32,
    I64,
    Double,
    Binary,
    List,
    Set,
    Map,
    Struct,
}

impl TType {
    fn from_u8(v: u8) -> TResult<TType> {
        Ok(match v {
            0 => TType::Stop,
            1 => TType::BoolTrue,
            2 => TType::BoolFalse,
            3 => TType::Byte,
            4 => TType::I16,
            5 => TType::I32,
            6 => TType::I64,
            7 => TType::Double,
            8 => TType::Binary,
            9 => TType::List,
            10 => TType::Set,
            11 => TType::Map,
            12 => TType::Struct,
            _ => return err("invalid thrift type"),
        })
    }
}

pub struct Reader<'a> {
    buf: &'a [u8],
    pos: usize,
    last_field: Vec<i16>,
    cur_field: i16,
    pending_bool: Option<bool>,
}

#[derive(Debug, Clone, Copy)]
pub struct FieldHeader {
    pub ttype: TType,
    pub id: i16,
}

impl<'a> Reader<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        Reader { buf, pos: 0, last_field: Vec::new(), cur_field: 0, pending_bool: None }
    }

    pub fn position(&self) -> usize {
        self.pos
    }

    pub fn read_byte(&mut self) -> TResult<u8> {
        if self.pos >= self.buf.len() {
            return err("unexpected end of thrift data");
        }
        let b = self.buf[self.pos];
        self.pos += 1;
        Ok(b)
    }

    fn read_varint(&mut self) -> TResult<u64> {
        let mut result: u64 = 0;
        let mut shift = 0;
        loop {
            let b = self.read_byte()?;
            if shift >= 64 {
                return err("varint too long");
            }
            result |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                return Ok(result);
            }
        }
    }

    fn read_zigzag(&mut self) -> TResult<i64> {
        let n = self.read_varint()?;
        Ok(((n >> 1) as i64) ^ -((n & 1) as i64))
    }

    pub fn read_struct_begin(&mut self) -> TResult<()> {
        self.last_field.push(self.cur_field);
        self.cur_field = 0;
        Ok(())
    }

    pub fn read_struct_end(&mut self) -> TResult<()> {
        self.cur_field = self.last_field.pop().unwrap_or(0);
        Ok(())
    }

    pub fn read_field_begin(&mut self) -> TResult<FieldHeader> {
        let b = self.read_byte()?;
        let ttype_raw = b & 0x0f;
        let delta = b >> 4;
        if ttype_raw == 0 {
            return Ok(FieldHeader { ttype: TType::Stop, id: 0 });
        }
        let id = if delta == 0 {
            self.read_zigzag()? as i16
        } else {
            self.cur_field.wrapping_add(delta as i16)
        };
        self.cur_field = id;
        let ttype = TType::from_u8(ttype_raw)?;
        match ttype {
            TType::BoolTrue => self.pending_bool = Some(true),
            TType::BoolFalse => self.pending_bool = Some(false),
            _ => {}
        }
        Ok(FieldHeader { ttype, id })
    }

    pub fn read_bool(&mut self) -> TResult<bool> {
        if let Some(b) = self.pending_bool.take() {
            return Ok(b);
        }
        let b = self.read_byte()?;
        Ok(b == 1)
    }

    pub fn read_i8(&mut self) -> TResult<i8> {
        Ok(self.read_byte()? as i8)
    }

    pub fn read_i16(&mut self) -> TResult<i16> {
        Ok(self.read_zigzag()? as i16)
    }

    pub fn read_i32(&mut self) -> TResult<i32> {
        Ok(self.read_zigzag()? as i32)
    }

    pub fn read_i64(&mut self) -> TResult<i64> {
        self.read_zigzag()
    }

    pub fn read_double(&mut self) -> TResult<f64> {
        if self.pos + 8 > self.buf.len() {
            return err("unexpected end of thrift data");
        }
        let mut arr = [0u8; 8];
        arr.copy_from_slice(&self.buf[self.pos..self.pos + 8]);
        self.pos += 8;
        Ok(f64::from_le_bytes(arr))
    }

    pub fn read_bytes(&mut self) -> TResult<Vec<u8>> {
        let len = self.read_varint()? as usize;
        if self.pos + len > self.buf.len() {
            return err("unexpected end of thrift data");
        }
        let v = self.buf[self.pos..self.pos + len].to_vec();
        self.pos += len;
        Ok(v)
    }

    pub fn read_string(&mut self) -> TResult<String> {
        let b = self.read_bytes()?;
        Ok(String::from_utf8_lossy(&b).into_owned())
    }

    /// Returns (element type, size)
    pub fn read_list_begin(&mut self) -> TResult<(TType, usize)> {
        let b = self.read_byte()?;
        let et = TType::from_u8(b & 0x0f)?;
        let mut size = (b >> 4) as usize;
        if size == 15 {
            size = self.read_varint()? as usize;
        }
        Ok((et, size))
    }

    pub fn read_map_begin(&mut self) -> TResult<(TType, TType, usize)> {
        let size = self.read_varint()? as usize;
        if size == 0 {
            return Ok((TType::Stop, TType::Stop, 0));
        }
        let b = self.read_byte()?;
        let kt = TType::from_u8(b >> 4)?;
        let vt = TType::from_u8(b & 0x0f)?;
        Ok((kt, vt, size))
    }

    pub fn skip(&mut self, ttype: TType) -> TResult<()> {
        match ttype {
            TType::Stop => err("cannot skip stop"),
            TType::BoolTrue | TType::BoolFalse => {
                self.read_bool()?;
                Ok(())
            }
            TType::Byte => {
                self.read_byte()?;
                Ok(())
            }
            TType::I16 | TType::I32 | TType::I64 => {
                self.read_zigzag()?;
                Ok(())
            }
            TType::Double => {
                self.read_double()?;
                Ok(())
            }
            TType::Binary => {
                self.read_bytes()?;
                Ok(())
            }
            TType::List | TType::Set => {
                let (et, n) = self.read_list_begin()?;
                for _ in 0..n {
                    self.skip(et)?;
                }
                Ok(())
            }
            TType::Map => {
                let (kt, vt, n) = self.read_map_begin()?;
                for _ in 0..n {
                    self.skip(kt)?;
                    self.skip(vt)?;
                }
                Ok(())
            }
            TType::Struct => {
                self.read_struct_begin()?;
                loop {
                    let fh = self.read_field_begin()?;
                    if fh.ttype == TType::Stop {
                        break;
                    }
                    self.skip(fh.ttype)?;
                }
                self.read_struct_end()
            }
        }
    }
}
