}

impl Statistics {
    /// Effective min bytes (prefers `min_value`).
    pub fn min_bytes(&self) -> Option<&Vec<u8>> {
        self.min_value.as_ref().or(self.min.as_ref())
    }
    pub fn max_bytes(&self) -> Option<&Vec<u8>> {
        self.max_value.as_ref().or(self.max.as_ref())
    }
    /// Whether the min/max come from the deprecated fields only.
    pub fn is_deprecated_min_max(&self) -> bool {
        self.min_value.is_none() && self.max_value.is_none() && (self.min.is_some() || self.max.is_some())
    }
}

