// ---------------------------------------------------------------------------
// Parsing

#[derive(Debug, Clone)]
pub enum ParseError {
    /// Error whose message mirrors arrow-rs parquet "Parquet error: ..."
    General(String),
}

impl From<ThriftError> for ParseError {
    fn from(e: ThriftError) -> Self {
        ParseError::General(e.0)
    }
}

impl From<String> for ParseError {
    fn from(e: String) -> Self {
        ParseError::General(e)
    }
}

pub type PResult<T> = Result<T, ParseError>;

fn te(e: ThriftError) -> ParseError {
    ParseError::General(e.0)
}

macro_rules! read_struct {
    ($r:expr, |$fh:ident| $body:block) => {{
        $r.read_struct_begin().map_err(te)?;
        loop {
            let $fh = $r.read_field_begin().map_err(te)?;
            if $fh.ttype == TType::Stop {
                break;
            }
            $body
        }
        $r.read_struct_end().map_err(te)?;
    }};
}

fn read_i32_list(r: &mut Reader) -> PResult<Vec<i32>> {
    let (_, n) = r.read_list_begin().map_err(te)?;
    let mut v = Vec::with_capacity(n);
    for _ in 0..n {
        v.push(r.read_i32().map_err(te)?);
    }
    Ok(v)
}

fn read_string_list(r: &mut Reader) -> PResult<Vec<String>> {
    let (_, n) = r.read_list_begin().map_err(te)?;
    let mut v = Vec::with_capacity(n);
    for _ in 0..n {
        v.push(r.read_string().map_err(te)?);
    }
    Ok(v)
}

fn read_time_unit(r: &mut Reader) -> PResult<TimeUnit> {
    let mut unit = TimeUnit::Millis;
    read_struct!(r, |fh| {
        match fh.id {
            1 => {
                r.skip(fh.ttype).map_err(te)?;
                unit = TimeUnit::Millis;
            }
            2 => {
                r.skip(fh.ttype).map_err(te)?;
                unit = TimeUnit::Micros;
            }
            3 => {
                r.skip(fh.ttype).map_err(te)?;
                unit = TimeUnit::Nanos;
            }
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(unit)
}

fn read_logical_type(r: &mut Reader) -> PResult<Option<LogicalType>> {
    let mut lt = None;
    read_struct!(r, |fh| {
        match fh.id {
            1 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::String);
            }
            2 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Map);
            }
            3 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::List);
            }
            4 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Enum);
            }
            5 => {
                let mut scale = 0;
                let mut precision = 0;
                read_struct!(r, |f2| {
                    match f2.id {
                        1 => scale = r.read_i32().map_err(te)?,
                        2 => precision = r.read_i32().map_err(te)?,
                        _ => r.skip(f2.ttype).map_err(te)?,
                    }
                });
                lt = Some(LogicalType::Decimal { scale, precision });
            }
            6 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Date);
            }
            7 | 8 => {
                let mut adj = false;
                let mut unit = TimeUnit::Millis;
                read_struct!(r, |f2| {
                    match f2.id {
                        1 => adj = r.read_bool().map_err(te)?,
                        2 => unit = read_time_unit(r)?,
                        _ => r.skip(f2.ttype).map_err(te)?,
                    }
                });
                lt = Some(if fh.id == 7 {
                    LogicalType::Time { is_adjusted_to_utc: adj, unit }
                } else {
                    LogicalType::Timestamp { is_adjusted_to_utc: adj, unit }
                });
            }
            10 => {
                let mut bw = 0i8;
                let mut signed = false;
                read_struct!(r, |f2| {
                    match f2.id {
                        1 => bw = r.read_i8().map_err(te)?,
                        2 => signed = r.read_bool().map_err(te)?,
                        _ => r.skip(f2.ttype).map_err(te)?,
                    }
                });
                lt = Some(LogicalType::Integer { bit_width: bw, is_signed: signed });
            }
            11 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Unknown);
            }
            12 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Json);
            }
            13 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Bson);
            }
            14 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Uuid);
            }
            15 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Float16);
            }
            16 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Variant);
            }
            17 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Geometry);
            }
            18 => {
                r.skip(fh.ttype).map_err(te)?;
                lt = Some(LogicalType::Geography);
            }
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(lt)
}

fn read_schema_element(r: &mut Reader) -> PResult<SchemaElement> {
    let mut e = SchemaElement {
        physical_type: None,
        type_length: None,
        repetition: None,
        name: String::new(),
        num_children: None,
        converted_type: None,
        scale: None,
        precision: None,
        field_id: None,
        logical_type: None,
    };
    read_struct!(r, |fh| {
        match fh.id {
            1 => e.physical_type = Some(PhysicalType::from_i32(r.read_i32().map_err(te)?)?),
            2 => e.type_length = Some(r.read_i32().map_err(te)?),
            3 => e.repetition = Some(Repetition::from_i32(r.read_i32().map_err(te)?)?),
            4 => e.name = r.read_string().map_err(te)?,
            5 => e.num_children = Some(r.read_i32().map_err(te)?),
            6 => e.converted_type = Some(ConvertedType::from_i32(r.read_i32().map_err(te)?)?),
            7 => e.scale = Some(r.read_i32().map_err(te)?),
            8 => e.precision = Some(r.read_i32().map_err(te)?),
            9 => e.field_id = Some(r.read_i32().map_err(te)?),
            10 => e.logical_type = read_logical_type(r)?,
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(e)
}

pub fn read_statistics(r: &mut Reader) -> PResult<Statistics> {
    let mut s = Statistics::default();
    read_struct!(r, |fh| {
        match fh.id {
            1 => s.max = Some(r.read_bytes().map_err(te)?),
            2 => s.min = Some(r.read_bytes().map_err(te)?),
            3 => s.null_count = Some(r.read_i64().map_err(te)?),
            4 => s.distinct_count = Some(r.read_i64().map_err(te)?),
            5 => s.max_value = Some(r.read_bytes().map_err(te)?),
            6 => s.min_value = Some(r.read_bytes().map_err(te)?),
            7 => s.is_max_value_exact = Some(r.read_bool().map_err(te)?),
            8 => s.is_min_value_exact = Some(r.read_bool().map_err(te)?),
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(s)
}

fn read_column_metadata(r: &mut Reader) -> PResult<ColumnMetaData> {
    let mut physical_type: Option<PhysicalType> = None;
    let mut encodings = Vec::new();
    let mut path_in_schema = Vec::new();
    let mut codec: Option<Compression> = None;
    let mut num_values = 0i64;
    let mut total_uncompressed_size = 0i64;
    let mut total_compressed_size = 0i64;
    let mut data_page_offset = 0i64;
    let mut index_page_offset = None;
    let mut dictionary_page_offset = None;
    let mut statistics = None;
    let mut encoding_stats = None;
    let mut bloom_filter_offset = None;
    let mut bloom_filter_length = None;
    read_struct!(r, |fh| {
        match fh.id {
            1 => physical_type = Some(PhysicalType::from_i32(r.read_i32().map_err(te)?)?),
            2 => {
                let ids = read_i32_list(r)?;
                for id in ids {
                    encodings.push(Encoding::from_i32(id)?);
                }
            }
            3 => path_in_schema = read_string_list(r)?,
            4 => codec = Some(Compression::from_i32(r.read_i32().map_err(te)?)?),
            5 => num_values = r.read_i64().map_err(te)?,
            6 => total_uncompressed_size = r.read_i64().map_err(te)?,
            7 => total_compressed_size = r.read_i64().map_err(te)?,
            9 => data_page_offset = r.read_i64().map_err(te)?,
            10 => index_page_offset = Some(r.read_i64().map_err(te)?),
            11 => dictionary_page_offset = Some(r.read_i64().map_err(te)?),
            12 => statistics = Some(read_statistics(r)?),
            13 => {
                let (_, n) = r.read_list_begin().map_err(te)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let mut page_type = 0;
                    let mut encoding = Encoding::Plain;
                    let mut count = 0;
                    read_struct!(r, |f2| {
                        match f2.id {
                            1 => page_type = r.read_i32().map_err(te)?,
                            2 => encoding = Encoding::from_i32(r.read_i32().map_err(te)?)?,
                            3 => count = r.read_i32().map_err(te)?,
                            _ => r.skip(f2.ttype).map_err(te)?,
                        }
                    });
                    v.push(PageEncodingStats { page_type, encoding, count });
                }
                encoding_stats = Some(v);
            }
            14 => bloom_filter_offset = Some(r.read_i64().map_err(te)?),
            15 => bloom_filter_length = Some(r.read_i32().map_err(te)?),
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(ColumnMetaData {
        physical_type: physical_type.ok_or_else(|| ParseError::General("Required field type is missing".into()))?,
        encodings,
        path_in_schema,
        codec: codec.ok_or_else(|| ParseError::General("Required field codec is missing".into()))?,
        num_values,
        total_uncompressed_size,
        total_compressed_size,
        data_page_offset,
        index_page_offset,
        dictionary_page_offset,
        statistics,
        encoding_stats,
        bloom_filter_offset,
        bloom_filter_length,
    })
}

fn read_column_chunk(r: &mut Reader) -> PResult<ColumnChunk> {
    let mut cc = ColumnChunk {
        file_path: None,
        file_offset: 0,
        meta_data: None,
        offset_index_offset: None,
        offset_index_length: None,
        column_index_offset: None,
        column_index_length: None,
        encrypted_column_metadata: None,
        has_crypto_metadata: false,
    };
    read_struct!(r, |fh| {
        match fh.id {
            1 => cc.file_path = Some(r.read_string().map_err(te)?),
            2 => cc.file_offset = r.read_i64().map_err(te)?,
            3 => cc.meta_data = Some(read_column_metadata(r)?),
            4 => cc.offset_index_offset = Some(r.read_i64().map_err(te)?),
            5 => cc.offset_index_length = Some(r.read_i32().map_err(te)?),
            6 => cc.column_index_offset = Some(r.read_i64().map_err(te)?),
            7 => cc.column_index_length = Some(r.read_i32().map_err(te)?),
            8 => {
                r.skip(fh.ttype).map_err(te)?;
                cc.has_crypto_metadata = true;
            }
            9 => cc.encrypted_column_metadata = Some(r.read_bytes().map_err(te)?),
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(cc)
}

fn read_row_group(r: &mut Reader) -> PResult<RowGroup> {
    let mut rg = RowGroup {
        columns: Vec::new(),
        total_byte_size: 0,
        num_rows: 0,
        file_offset: None,
        total_compressed_size: None,
        ordinal: None,
    };
    read_struct!(r, |fh| {
        match fh.id {
            1 => {
                let (_, n) = r.read_list_begin().map_err(te)?;
                for _ in 0..n {
                    rg.columns.push(read_column_chunk(r)?);
                }
            }
            2 => rg.total_byte_size = r.read_i64().map_err(te)?,
            3 => rg.num_rows = r.read_i64().map_err(te)?,
            5 => rg.file_offset = Some(r.read_i64().map_err(te)?),
            6 => rg.total_compressed_size = Some(r.read_i64().map_err(te)?),
            7 => rg.ordinal = Some(r.read_i16().map_err(te)?),
            _ => r.skip(fh.ttype).map_err(te)?,
        }
    });
    Ok(rg)
}

pub fn parse_file_metadata(buf: &[u8]) -> PResult<FileMetaData> {
    let mut r = Reader::new(buf);
    let mut version = 0;
    let mut schema = Vec::new();
    let mut num_rows = 0;
    let mut row_groups = Vec::new();
    let mut key_value_metadata = None;
    let mut created_by = None;
    {
        let r = &mut r;
        read_struct!(r, |fh| {
            match fh.id {
                1 => version = r.read_i32().map_err(te)?,
                2 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    for _ in 0..n {
                        schema.push(read_schema_element(r)?);
                    }
                }
                3 => num_rows = r.read_i64().map_err(te)?,
                4 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    for _ in 0..n {
                        row_groups.push(read_row_group(r)?);
                    }
                }
                5 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    let mut kvs = Vec::with_capacity(n);
                    for _ in 0..n {
                        let mut key = String::new();
                        let mut value = None;
                        read_struct!(r, |f2| {
                            match f2.id {
                                1 => key = r.read_string().map_err(te)?,
                                2 => value = Some(r.read_string().map_err(te)?),
                                _ => r.skip(f2.ttype).map_err(te)?,
                            }
                        });
                        kvs.push(KeyValue { key, value });
                    }
                    key_value_metadata = Some(kvs);
                }
                6 => created_by = Some(r.read_string().map_err(te)?),
                _ => r.skip(fh.ttype).map_err(te)?,
            }
        });
    }
    Ok(FileMetaData { version, schema, num_rows, row_groups, key_value_metadata, created_by })
}

/// Parse a page header starting at `buf[0]`. Returns the header and the number of bytes consumed.
pub fn parse_page_header(buf: &[u8]) -> TResult<(PageHeader, usize)> {
    let mut r = Reader::new(buf);
    let mut page_type = None;
    let mut uncompressed_page_size = 0;
    let mut compressed_page_size = 0;
    let mut crc = None;
    let mut data_page_header = None;
    let mut dictionary_page_header = None;
    let mut data_page_header_v2 = None;
    r.read_struct_begin()?;
    loop {
        let fh = r.read_field_begin()?;
        if fh.ttype == TType::Stop {
            break;
        }
        match fh.id {
            1 => page_type = Some(r.read_i32()?),
            2 => uncompressed_page_size = r.read_i32()?,
            3 => compressed_page_size = r.read_i32()?,
            4 => crc = Some(r.read_i32()?),
            5 => {
                let mut h = DataPageHeader {
                    num_values: 0,
                    encoding: Encoding::Plain,
                    definition_level_encoding: Encoding::Rle,
                    repetition_level_encoding: Encoding::Rle,
                    statistics: None,
                };
                r.read_struct_begin()?;
                loop {
                    let f2 = r.read_field_begin()?;
                    if f2.ttype == TType::Stop {
                        break;
                    }
                    match f2.id {
                        1 => h.num_values = r.read_i32()?,
                        2 => h.encoding = Encoding::from_i32(r.read_i32()?).map_err(ThriftError)?,
                        3 => h.definition_level_encoding = Encoding::from_i32(r.read_i32()?).map_err(ThriftError)?,
                        4 => h.repetition_level_encoding = Encoding::from_i32(r.read_i32()?).map_err(ThriftError)?,
                        5 => {
                            h.statistics = Some(read_statistics(&mut r).map_err(|e| match e {
                                ParseError::General(s) => ThriftError(s),
                            })?)
                        }
                        _ => r.skip(f2.ttype)?,
                    }
                }
                r.read_struct_end()?;
                data_page_header = Some(h);
            }
            7 => {
                let mut h = DictionaryPageHeader { num_values: 0, encoding: Encoding::Plain, is_sorted: None };
                r.read_struct_begin()?;
                loop {
                    let f2 = r.read_field_begin()?;
                    if f2.ttype == TType::Stop {
                        break;
                    }
                    match f2.id {
                        1 => h.num_values = r.read_i32()?,
                        2 => h.encoding = Encoding::from_i32(r.read_i32()?).map_err(ThriftError)?,
                        3 => h.is_sorted = Some(r.read_bool()?),
                        _ => r.skip(f2.ttype)?,
                    }
                }
                r.read_struct_end()?;
                dictionary_page_header = Some(h);
            }
            8 => {
                let mut h = DataPageHeaderV2 {
                    num_values: 0,
                    num_nulls: 0,
                    num_rows: 0,
                    encoding: Encoding::Plain,
                    definition_levels_byte_length: 0,
                    repetition_levels_byte_length: 0,
                    is_compressed: true,
                    statistics: None,
                };
                r.read_struct_begin()?;
                loop {
                    let f2 = r.read_field_begin()?;
                    if f2.ttype == TType::Stop {
                        break;
                    }
                    match f2.id {
                        1 => h.num_values = r.read_i32()?,
                        2 => h.num_nulls = r.read_i32()?,
                        3 => h.num_rows = r.read_i32()?,
                        4 => h.encoding = Encoding::from_i32(r.read_i32()?).map_err(ThriftError)?,
                        5 => h.definition_levels_byte_length = r.read_i32()?,
                        6 => h.repetition_levels_byte_length = r.read_i32()?,
                        7 => h.is_compressed = r.read_bool()?,
                        8 => {
                            h.statistics = Some(read_statistics(&mut r).map_err(|e| match e {
                                ParseError::General(s) => ThriftError(s),
                            })?)
                        }
                        _ => r.skip(f2.ttype)?,
                    }
                }
                r.read_struct_end()?;
                data_page_header_v2 = Some(h);
            }
            _ => r.skip(fh.ttype)?,
        }
    }
    r.read_struct_end()?;
    let page_type = PageType::from_i32(page_type.ok_or_else(|| ThriftError("missing page type".into()))?)
        .map_err(ThriftError)?;
    Ok((
        PageHeader {
            page_type,
            uncompressed_page_size,
            compressed_page_size,
            crc,
            data_page_header,
            dictionary_page_header,
            data_page_header_v2,
        },
        r.position(),
    ))
}
EOF
echo done"}

