                    let mut count = 0;
                    read_struct!(r, |f2| {
                        match f2.id {
                            1 => page_type = r.read_i32().map_err(te)?,
                            2 => encoding = Encoding::from_i32(r.read_i32().map_err(te)?)?,
                            3 => count = r.read_i32().map_err(te)?,
                            _ => r.skip(f2.ttype).map_err(te)?,
                        }
                    });
                    v.push(PageEncodingStats { page_type, encoding, count });
                }
                encoding_stats = Some(v);
            }
            14 => bloom_filter_offset = Some(r.read_i64().map_err(te)?),
            15 => bloom_filter_length = Some(r.read_i32().map_err(te)?),
            _ => r.skip(fh.ttype).map_err(te)?,
