pub fn parse_file_metadata(buf: &[u8]) -> PResult<FileMetaData> {
    let mut r = Reader::new(buf);
    let mut version = 0;
    let mut schema = Vec::new();
    let mut num_rows = 0;
    let mut row_groups = Vec::new();
    let mut key_value_metadata = None;
    let mut created_by = None;
    {
        let r = &mut r;
        read_struct!(r, |fh| {
            match fh.id {
                1 => version = r.read_i32().map_err(te)?,
                2 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    for _ in 0..n {
                        schema.push(read_schema_element(r)?);
                    }
                }
                3 => num_rows = r.read_i64().map_err(te)?,
                4 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    for _ in 0..n {
                        row_groups.push(read_row_group(r)?);
                    }
                }
                5 => {
                    let (_, n) = r.read_list_begin().map_err(te)?;
                    let mut kvs = Vec::with_capacity(n);
                    for _ in 0..n {
                        let mut key = String::new();
                        let mut value = None;
                        read_struct!(r, |f2| {
                            match f2.id {
                                1 => key = r.read_string().map_err(te)?,
                                2 => value = Some(r.read_string().map_err(te)?),
