// ---------------------------------------------------------------------------
// Bit reader

pub struct BitReader<'a> {
    data: &'a [u8],
    byte_pos: usize,
    bit_pos: u32,
}

impl<'a> BitReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        BitReader { data, byte_pos: 0, bit_pos: 0 }
    }
    pub fn read_bits(&mut self, n: u32) -> Option<u64> {
        if n == 0 {
            return Some(0);
        }
        let mut result: u64 = 0;
        let mut got = 0u32;
        while got < n {
            if self.byte_pos >= self.data.len() {
                return None;
            }
            let avail = 8 - self.bit_pos;
            let take = (n - got).min(avail);
            let byte = self.data[self.byte_pos] as u64;
            let bits = (byte >> self.bit_pos) & ((1u64 << take) - 1);
            result |= bits << got;
            got += take;
            self.bit_pos += take;
            if self.bit_pos == 8 {
                self.bit_pos = 0;
                self.byte_pos += 1;
            }
        }
        Some(result)
    }
    pub fn align(&mut self) {
        if self.bit_pos != 0 {
            self.bit_pos = 0;
            self.byte_pos += 1;
        }
    }
    pub fn position(&self) -> usize {
        self.byte_pos
    }
    pub fn read_vlq(&mut self) -> Option<u64> {
        self.align();
        let mut r = 0u64;
        let mut shift = 0;
        loop {
            if self.byte_pos >= self.data.len() || shift >= 64 {
                return None;
            }
            let b = self.data[self.byte_pos];
            self.byte_pos += 1;
            r |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                return Some(r);
            }
        }
    }
    pub fn read_zigzag_vlq(&mut self) -> Option<i64> {
        let v = self.read_vlq()?;
        Some(((v >> 1) as i64) ^ -((v & 1) as i64))
    }
    pub fn remaining(&self) -> &'a [u8] {
        &self.data[self.byte_pos.min(self.data.len())..]
    }
}

fn read_u32_le(data: &[u8], pos: usize) -> DResult<u32> {
    if pos + 4 > data.len() {
        return Err("unexpected end of page data".into());
    }
    Ok(u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]))
}

/// Decode an RLE / bit-packed hybrid run of `num_values` values with `bit_width`.
/// Returns the decoded values and the number of bytes consumed.
pub fn decode_hybrid(data: &[u8], bit_width: u32, num_values: usize) -> DResult<(Vec<u32>, usize)> {
    let mut out: Vec<u32> = Vec::with_capacity(num_values);
    let mut pos = 0usize;
    let byte_width = ((bit_width + 7) / 8) as usize;
    while out.len() < num_values {
        if pos >= data.len() {
            break;
        }
        // read varint header
        let mut header: u64 = 0;
        let mut shift = 0;
        loop {
            if pos >= data.len() {
                return Err("unexpected end of rle data".into());
            }
            let b = data[pos];
            pos += 1;
            header |= ((b & 0x7f) as u64) << shift;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
            if shift > 63 {
                return Err("invalid rle header".into());
            }
        }
        if header & 1 == 0 {
            // RLE run
            let count = (header >> 1) as usize;
            if pos + byte_width > data.len() {
                return Err("unexpected end of rle data".into());
            }
            let mut v: u32 = 0;
            for i in 0..byte_width {
                v |= (data[pos + i] as u32) << (8 * i);
            }
            pos += byte_width;
            let take = count.min(num_values - out.len());
            out.extend(std::iter::repeat(v).take(take));
        } else {
            // bit-packed run
            let groups = (header >> 1) as usize;
            let count = groups * 8;
            let nbytes = (count * bit_width as usize + 7) / 8;
            if pos + nbytes > data.len() {
                return Err("unexpected end of bit-packed data".into());
            }
            let mut br = BitReader::new(&data[pos..pos + nbytes]);
            let take = count.min(num_values - out.len());
            for _ in 0..take {
                let v = br.read_bits(bit_width).ok_or_else(|| DecodeError("bit-packed read failed".into()))?;
                out.push(v as u32);
            }
            pos += nbytes;
        }
    }
    if out.len() < num_values {
        // pad with zeros (lenient)
        out.resize(num_values, 0);
    }
    Ok((out, pos))
}

fn bit_width_for(max_level: i16) -> u32 {
    if max_level <= 0 {
        0
    } else {
        32 - (max_level as u32).leading_zeros()
    }
}

/// Decode levels for a V1 data page (4-byte length prefix). Returns levels and bytes consumed.
fn decode_levels_v1(data: &[u8], max_level: i16, num_values: usize, encoding: Encoding) -> DResult<(Vec<i16>, usize)> {
    if max_level == 0 {
        return Ok((vec![0; num_values], 0));
    }
    let bw = bit_width_for(max_level);
    match encoding {
        Encoding::Rle => {
            let len = read_u32_le(data, 0)? as usize;
            if 4 + len > data.len() {
                return Err("level data out of bounds".into());
            }
            let (vals, _) = decode_hybrid(&data[4..4 + len], bw, num_values)?;
            Ok((vals.into_iter().map(|v| v as i16).collect(), 4 + len))
        }
        Encoding::BitPacked => {
            // legacy bit packed: MSB-first bit packing, no length prefix
            let nbytes = (num_values * bw as usize + 7) / 8;
            if nbytes > data.len() {
                return Err("level data out of bounds".into());
            }
            let mut out = Vec::with_capacity(num_values);
            let mut bitpos = 0usize;
            for _ in 0..num_values {
                let mut v = 0u32;
                for _ in 0..bw {
                    let byte = data[bitpos / 8];
                    let bit = (byte >> (7 - (bitpos % 8))) & 1;
                    v = (v << 1) | bit as u32;
                    bitpos += 1;
                }
                out.push(v as i16);
            }
            Ok((out, nbytes))
        }
        _ => Err(format!("unsupported level encoding {:?}", encoding).into()),
    }
}

fn decode_levels_v2(data: &[u8], max_level: i16, num_values: usize) -> DResult<Vec<i16>> {
    if max_level == 0 {
        return Ok(vec![0; num_values]);
    }
    let bw = bit_width_for(max_level);
    let (vals, _) = decode_hybrid(data, bw, num_values)?;
    Ok(vals.into_iter().map(|v| v as i16).collect())
}

// ---------------------------------------------------------------------------
// PLAIN decoding

fn decode_plain(data: &[u8], pt: PhysicalType, num_values: usize, type_length: usize) -> DResult<Values> {
    match pt {
        PhysicalType::Boolean => {
            let mut br = BitReader::new(data);
            let mut out = Vec::with_capacity(num_values);
            for _ in 0..num_values {
                let b = br.read_bits(1).ok_or_else(|| DecodeError("unexpected end of boolean data".into()))?;
                out.push(b != 0);
            }
            Ok(Values::Bool(out))
        }
        PhysicalType::Int32 => {
            if data.len() < num_values * 4 {
                return Err("unexpected end of int32 data".into());
            }
            Ok(Values::I32(
                (0..num_values)
                    .map(|i| i32::from_le_bytes([data[i * 4], data[i * 4 + 1], data[i * 4 + 2], data[i * 4 + 3]]))
                    .collect(),
            ))
        }
        PhysicalType::Int64 => {
            if data.len() < num_values * 8 {
                return Err("unexpected end of int64 data".into());
            }
            Ok(Values::I64(
                (0..num_values)
                    .map(|i| {
                        let mut a = [0u8; 8];
                        a.copy_from_slice(&data[i * 8..i * 8 + 8]);
                        i64::from_le_bytes(a)
                    })
                    .collect(),
            ))
        }
        PhysicalType::Int96 => {
            if data.len() < num_values * 12 {
                return Err("unexpected end of int96 data".into());
            }
            Ok(Values::I96(
                (0..num_values)
                    .map(|i| {
                        let b = &data[i * 12..i * 12 + 12];
                        [
                            u32::from_le_bytes([b[0], b[1], b[2], b[3]]),
                            u32::from_le_bytes([b[4], b[5], b[6], b[7]]),
                            u32::from_le_bytes([b[8], b[9], b[10], b[11]]),
                        ]
                    })
                    .collect(),
            ))
        }
        PhysicalType::Float => {
            if data.len() < num_values * 4 {
                return Err("unexpected end of float data".into());
            }
            Ok(Values::F32(
                (0..num_values)
                    .map(|i| f32::from_le_bytes([data[i * 4], data[i * 4 + 1], data[i * 4 + 2], data[i * 4 + 3]]))
                    .collect(),
            ))
        }
        PhysicalType::Double => {
            if data.len() < num_values * 8 {
                return Err("unexpected end of double data".into());
            }
            Ok(Values::F64(
                (0..num_values)
                    .map(|i| {
                        let mut a = [0u8; 8];
                        a.copy_from_slice(&data[i * 8..i * 8 + 8]);
                        f64::from_le_bytes(a)
                    })
                    .collect(),
            ))
        }
        PhysicalType::ByteArray => {
            let mut out = Vec::with_capacity(num_values);
            let mut pos = 0;
            for _ in 0..num_values {
                let len = read_u32_le(data, pos)? as usize;
                pos += 4;
                if pos + len > data.len() {
                    return Err("unexpected end of byte array data".into());
                }
                out.push(data[pos..pos + len].to_vec());
                pos += len;
            }
            Ok(Values::Bytes(out))
        }
        PhysicalType::FixedLenByteArray => {
            if data.len() < num_values * type_length {
                return Err("unexpected end of fixed len byte array data".into());
            }
            Ok(Values::Bytes((0..num_values).map(|i| data[i * type_length..(i + 1) * type_length].to_vec()).collect()))
        }
    }
}

// ---------------------------------------------------------------------------
// DELTA encodings

fn decode_delta_binary_packed(data: &[u8], num_values: usize) -> DResult<(Vec<i64>, usize)> {
    let mut br = BitReader::new(data);
    let block_size = br.read_vlq().ok_or("delta: missing block size")? as usize;
    let mini_blocks = br.read_vlq().ok_or("delta: missing miniblock count")? as usize;
    let total_count = br.read_vlq().ok_or("delta: missing count")? as usize;
    let first = br.read_zigzag_vlq().ok_or("delta: missing first value")?;
    if mini_blocks == 0 {
        return Err("delta: zero miniblocks".into());
    }
    let values_per_mini = block_size / mini_blocks;
    let mut out = Vec::with_capacity(total_count.max(num_values));
    if total_count > 0 {
        out.push(first);
    }
    let mut cur = first;
    while out.len() < total_count {
        let min_delta = br.read_zigzag_vlq().ok_or("delta: missing min delta")?;
        let mut widths = Vec::with_capacity(mini_blocks);
        for _ in 0..mini_blocks {
            let w = br.read_bits(8).ok_or("delta: missing bit widths")? as u32;
            widths.push(w);
        }
        for w in widths {
            if out.len() >= total_count {
                break;
            }
            for _ in 0..values_per_mini {
                if out.len() >= total_count {
                    // still must consume the rest of the miniblock bits
                    let _ = br.read_bits(w);
                    continue;
                }
                let d = br.read_bits(w).ok_or("delta: unexpected end of data")? as i64;
                cur = cur.wrapping_add(min_delta).wrapping_add(d);
                out.push(cur);
            }
        }
    }
    br.align();
    Ok((out, br.position()))
}

fn decode_delta_length_byte_array(data: &[u8], num_values: usize) -> DResult<Vec<Vec<u8>>> {
    let (lengths, consumed) = decode_delta_binary_packed(data, num_values)?;
    let mut pos = consumed;
    let mut out = Vec::with_capacity(lengths.len());
    for len in lengths.iter() {
        let len = *len as usize;
        if pos + len > data.len() {
            return Err("delta length: unexpected end of data".into());
        }
        out.push(data[pos..pos + len].to_vec());
        pos += len;
    }
    Ok(out)
}

fn decode_delta_byte_array(data: &[u8], num_values: usize) -> DResult<Vec<Vec<u8>>> {
    let (prefix_lens, consumed) = decode_delta_binary_packed(data, num_values)?;
    let suffixes = decode_delta_length_byte_array(&data[consumed..], num_values)?;
    let mut out: Vec<Vec<u8>> = Vec::with_capacity(prefix_lens.len());
    let mut prev: Vec<u8> = Vec::new();
    for (i, plen) in prefix_lens.iter().enumerate() {
        let plen = *plen as usize;
        if plen > prev.len() {
            return Err("delta byte array: prefix too long".into());
        }
        let mut v = prev[..plen].to_vec();
        if let Some(s) = suffixes.get(i) {
            v.extend_from_slice(s);
        }
        prev = v.clone();
        out.push(v);
    }
    Ok(out)
}

fn decode_byte_stream_split(data: &[u8], pt: PhysicalType, num_values: usize, type_length: usize) -> DResult<Values> {
    let width = match pt {
        PhysicalType::Float | PhysicalType::Int32 => 4,
        PhysicalType::Double | PhysicalType::Int64 => 8,
        PhysicalType::FixedLenByteArray => type_length,
        _ => return Err("byte stream split: unsupported type".into()),
    };
    if data.len() < width * num_values {
        return Err("byte stream split: unexpected end of data".into());
    }
    let n = num_values;
    let mut joined = vec![0u8; n * width];
    for i in 0..n {
        for b in 0..width {
            joined[i * width + b] = data[b * n + i];
        }
    }
    decode_plain(&joined, pt, n, type_length)
}

// ---------------------------------------------------------------------------
// Column chunk reading

pub struct ColumnChunkReader<'a> {
    pub file: &'a [u8],
    pub meta: &'a ColumnMetaData,
    pub type_length: usize,
    pub max_def: i16,
    pub max_rep: i16,
}

fn decompress(codec: Compression, data: &[u8], uncompressed_size: usize) -> DResult<Vec<u8>> {
    compress::decompress(codec, data, uncompressed_size).map_err(DecodeError)
}

impl<'a> ColumnChunkReader<'a> {
    fn start_offset(&self) -> usize {
        let mut start = self.meta.data_page_offset;
        if let Some(d) = self.meta.dictionary_page_offset {
            if d > 0 && d < start {
                start = d;
            }
        }
        start.max(0) as usize
    }

    /// Iterate over page headers of the chunk, without decoding values.
    pub fn page_infos(&self) -> DResult<Vec<PageInfo>> {
        let mut pos = self.start_offset();
        let end = (self.start_offset() as i64 + self.meta.total_compressed_size).max(0) as usize;
        let end = end.min(self.file.len());
        let mut out = Vec::new();
        let mut values_seen: i64 = 0;
        while pos < end {
            let (hdr, consumed) = parse_page_header(&self.file[pos..end]).map_err(|e| DecodeError(e.0))?;
            pos += consumed;
            let (num_values, encoding) = match hdr.page_type {
                PageType::DataPage => {
                    let h = hdr.data_page_header.as_ref().ok_or("missing data page header")?;
                    values_seen += h.num_values as i64;
                    (h.num_values, h.encoding)
                }
                PageType::DataPageV2 => {
                    let h = hdr.data_page_header_v2.as_ref().ok_or("missing data page v2 header")?;
                    values_seen += h.num_values as i64;
                    (h.num_values, h.encoding)
                }
                PageType::DictionaryPage => {
                    let h = hdr.dictionary_page_header.as_ref().ok_or("missing dictionary page header")?;
                    (h.num_values, h.encoding)
                }
                PageType::IndexPage => (0, Encoding::Plain),
            };
            out.push(PageInfo {
                page_type: hdr.page_type,
                uncompressed_size: hdr.uncompressed_page_size,
                compressed_size: hdr.compressed_page_size,
                num_values,
                encoding,
            });
            if hdr.compressed_page_size < 0 {
                break;
            }
            pos += hdr.compressed_page_size as usize;
            if values_seen >= self.meta.num_values && self.meta.num_values > 0 {
                break;
            }
        }
        Ok(out)
    }

    /// Decode the column chunk. Stops once at least `max_rows` rows (rep level 0) are present.
    pub fn read(&self, max_rows: Option<usize>) -> DResult<ColumnData> {
        let pt = self.meta.physical_type;
        let mut pos = self.start_offset();
        let end = (self.start_offset() as i64 + self.meta.total_compressed_size).max(0) as usize;
        let end = end.min(self.file.len());
        let mut dictionary: Option<Values> = None;
        let mut def_levels: Vec<i16> = Vec::new();
        let mut rep_levels: Vec<i16> = Vec::new();
        let mut values = Values::new(pt);
        let mut values_seen: i64 = 0;
        let mut rows_seen: usize = 0;
        while pos < end {
            if let Some(mr) = max_rows {
                if rows_seen > mr {
                    break;
                }
            }
            if values_seen >= self.meta.num_values {
                break;
            }
            let (hdr, consumed) = parse_page_header(&self.file[pos..end]).map_err(|e| {
                DecodeError(format!("File out of specification: {}", e.0))
            })?;
            pos += consumed;
            if hdr.compressed_page_size < 0 {
                return Err("File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into());
            }
            let csize = hdr.compressed_page_size as usize;
            if pos + csize > end {
                return Err("File out of specification: The page header reported the wrong page size".into());
            }
            let raw = &self.file[pos..pos + csize];
            pos += csize;
            match hdr.page_type {
                PageType::DictionaryPage => {
                    let h = hdr.dictionary_page_header.as_ref().ok_or("missing dictionary page header")?;
                    if h.num_values < 0 {
                        return Err("File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into());
                    }
                    let data = decompress(self.meta.codec, raw, hdr.uncompressed_page_size.max(0) as usize)?;
                    let dict = decode_plain(&data, pt, h.num_values as usize, self.type_length)?;
                    dictionary = Some(dict);
                }
                PageType::DataPage => {
                    let h = hdr.data_page_header.as_ref().ok_or("missing data page header")?;
                    if h.num_values < 0 {
                        return Err("File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into());
                    }
                    let n = h.num_values as usize;
                    let data = decompress(self.meta.codec, raw, hdr.uncompressed_page_size.max(0) as usize)?;
                    let mut off = 0usize;
                    let (reps, c) = decode_levels_v1(&data[off..], self.max_rep, n, h.repetition_level_encoding)?;
                    off += c;
                    let (defs, c) = decode_levels_v1(&data[off..], self.max_def, n, h.definition_level_encoding)?;
                    off += c;
                    let non_null = defs.iter().filter(|&&d| d == self.max_def).count();
                    let vals = self.decode_values(&data[off..], h.encoding, non_null, &dictionary)?;
                    rows_seen += reps.iter().filter(|&&r| r == 0).count();
                    values_seen += n as i64;
                    rep_levels.extend(reps);
                    def_levels.extend(defs);
                    values.append(vals);
                }
                PageType::DataPageV2 => {
                    let h = hdr.data_page_header_v2.as_ref().ok_or("missing data page v2 header")?;
                    if h.num_values < 0 {
                        return Err("File out of specification: Number must be zero or positive: out of range integral type conversion attempted".into());
                    }
                    let n = h.num_values as usize;
                    let rl = h.repetition_levels_byte_length.max(0) as usize;
                    let dl = h.definition_levels_byte_length.max(0) as usize;
                    if rl + dl > raw.len() {
                        return Err("File out of specification: The page header reported the wrong page size".into());
                    }
                    let reps = decode_levels_v2(&raw[..rl], self.max_rep, n)?;
                    let defs = decode_levels_v2(&raw[rl..rl + dl], self.max_def, n)?;
                    let body = &raw[rl + dl..];
                    let body = if h.is_compressed && self.meta.codec != Compression::Uncompressed {
                        let usize_ = (hdr.uncompressed_page_size.max(0) as usize).saturating_sub(rl + dl);
                        decompress(self.meta.codec, body, usize_)?
                    } else {
                        body.to_vec()
                    };
                    let non_null = defs.iter().filter(|&&d| d == self.max_def).count();
                    let vals = self.decode_values(&body, h.encoding, non_null, &dictionary)?;
                    rows_seen += reps.iter().filter(|&&r| r == 0).count();
                    values_seen += n as i64;
                    rep_levels.extend(reps);
                    def_levels.extend(defs);
                    values.append(vals);
                }
                PageType::IndexPage => {}
            }
        }
        Ok(ColumnData { def_levels, rep_levels, values, max_def: self.max_def, max_rep: self.max_rep })
    }

    fn decode_values(&self, data: &[u8], encoding: Encoding, n: usize, dictionary: &Option<Values>) -> DResult<Values> {
        let pt = self.meta.physical_type;
        match encoding {
            Encoding::Plain => decode_plain(data, pt, n, self.type_length),
            Encoding::PlainDictionary | Encoding::RleDictionary => {
                let dict = dictionary.as_ref().ok_or("File out of specification: dictionary page missing")?;
                if n == 0 {
                    return Ok(Values::new(pt));
                }
                if data.is_empty() {
                    return Err("File out of specification: empty dictionary indices".into());
                }
                let bw = data[0] as u32;
                if bw > 32 {
                    return Err("File out of specification: invalid dictionary bit width".into());
                }
                let (idx, _) = decode_hybrid(&data[1..], bw, n)?;
                dict.index(&idx)
            }
            Encoding::Rle => {
                // boolean RLE
                if pt != PhysicalType::Boolean {
                    return Err("RLE encoding only supported for booleans".into());
                }
                let len = read_u32_le(data, 0)? as usize;
                if 4 + len > data.len() {
                    return Err("rle boolean data out of bounds".into());
                }
                let (vals, _) = decode_hybrid(&data[4..4 + len], 1, n)?;
                Ok(Values::Bool(vals.into_iter().map(|v| v != 0).collect()))
            }
            Encoding::DeltaBinaryPacked => {
                let (vals, _) = decode_delta_binary_packed(data, n)?;
                match pt {
                    PhysicalType::Int32 => Ok(Values::I32(vals.into_iter().take(n).map(|v| v as i32).collect())),
                    PhysicalType::Int64 => Ok(Values::I64(vals.into_iter().take(n).collect())),
                    _ => Err("delta binary packed: unsupported type".into()),
                }
            }
            Encoding::DeltaLengthByteArray => Ok(Values::Bytes(decode_delta_length_byte_array(data, n)?.into_iter().take(n).collect())),
            Encoding::DeltaByteArray => Ok(Values::Bytes(decode_delta_byte_array(data, n)?.into_iter().take(n).collect())),
            Encoding::ByteStreamSplit => decode_byte_stream_split(data, pt, n, self.type_length),
            _ => Err(format!("unsupported encoding {:?}", encoding).into()),
        }
    }
}
