//! Decompression codecs for parquet pages.

use super::metadata::Compression;
use super::zstd;
use std::io::Read;

pub fn decompress(codec: Compression, data: &[u8], uncompressed_size: usize) -> Result<Vec<u8>, String> {
    match codec {
        Compression::Uncompressed => Ok(data.to_vec()),
        Compression::Snappy => snappy_decompress(data),
        Compression::Gzip => {
            let mut out = Vec::with_capacity(uncompressed_size);
            let mut d = flate2::read::MultiGzDecoder::new(data);
            d.read_to_end(&mut out).map_err(|e| format!("gzip: {}", e))?;
            Ok(out)
        }
        Compression::Lz4 => lz4_hadoop_or_raw(data, uncompressed_size),
        Compression::Lz4Raw => lz4_block_decompress(data, uncompressed_size),
        Compression::Zstd => zstd::decompress(data, uncompressed_size),
        Compression::Brotli => Err("brotli compression is not supported".to_string()),
        Compression::Lzo => Err("LZO compression is not supported".to_string()),
    }
}

// ---------------------------------------------------------------------------
// Snappy (raw block format)

pub fn snappy_decompress(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut pos = 0usize;
    // uncompressed length varint
    let mut len: u64 = 0;
    let mut shift = 0;
    loop {
        if pos >= data.len() {
            return Err("snappy: truncated header".into());
        }
        let b = data[pos];
        pos += 1;
        len |= ((b & 0x7f) as u64) << shift;
        shift += 7;
        if b & 0x80 == 0 {
            break;
        }
        if shift > 35 {
            return Err("snappy: bad length".into());
        }
    }
    let len = len as usize;
    let mut out: Vec<u8> = Vec::with_capacity(len);
    while pos < data.len() {
        let tag = data[pos];
        pos += 1;
        match tag & 3 {
            0 => {
                let mut lit_len = (tag >> 2) as usize;
                if lit_len >= 60 {
                    let extra = lit_len - 59;
                    if pos + extra > data.len() {
                        return Err("snappy: truncated literal length".into());
                    }
                    let mut l = 0usize;
                    for i in 0..extra {
                        l |= (data[pos + i] as usize) << (8 * i);
                    }
                    pos += extra;
                    lit_len = l;
                }
                lit_len += 1;
                if pos + lit_len > data.len() {
                    return Err("snappy: truncated literal".into());
                }
                out.extend_from_slice(&data[pos..pos + lit_len]);
                pos += lit_len;
            }
            1 => {
                if pos >= data.len() {
