//! A compact Zstandard decompressor (RFC 8878), sufficient for parquet pages.

type R<T> = Result<T, String>;

fn e<T>(msg: &str) -> R<T> {
    Err(format!("zstd: {}", msg))
}

// ---------------------------------------------------------------------------
// Forward LE bit reader (used for FSE table descriptions)

struct FwdBits<'a> {
    data: &'a [u8],
    pos: usize, // bit position
}

impl<'a> FwdBits<'a> {
    fn new(data: &'a [u8]) -> Self {
        FwdBits { data, pos: 0 }
    }
    fn peek(&self, n: u32) -> u64 {
        let mut v = 0u64;
        for i in 0..n as usize {
            let bp = self.pos + i;
            let byte = self.data.get(bp / 8).copied().unwrap_or(0);
            let bit = (byte >> (bp % 8)) & 1;
            v |= (bit as u64) << i;
        }
        v
    }
    fn read(&mut self, n: u32) -> u64 {
        let v = self.peek(n);
        self.pos += n as usize;
        v
    }
    fn bytes_consumed(&self) -> usize {
        (self.pos + 7) / 8
    }
}

// ---------------------------------------------------------------------------
// Backward bit reader (Huffman / sequences)

struct BackBits<'a> {
    data: &'a [u8],
    // number of bits remaining (from start of data up to the current position)
    bits_left: i64,
}

impl<'a> BackBits<'a> {
    fn new(data: &'a [u8]) -> R<Self> {
        if data.is_empty() {
            return e("empty bitstream");
        }
        let last = data[data.len() - 1];
        if last == 0 {
            return e("bitstream has no end marker");
        }
        let pad = last.leading_zeros() as i64 + 1;
        Ok(BackBits { data, bits_left: data.len() as i64 * 8 - pad })
    }
    /// Read `n` bits (n <= 56). Bits beyond the start are returned as zeros.
    fn read(&mut self, n: u32) -> u64 {
        if n == 0 {
            return 0;
        }
        let v = self.peek(n);
        self.bits_left -= n as i64;
        v
    }
    fn peek(&self, n: u32) -> u64 {
        // bits [bits_left - n, bits_left)
        let start = self.bits_left - n as i64;
        let mut v = 0u64;
        for i in 0..n as i64 {
            let bp = start + i;
            if bp < 0 {
                continue;
            }
            let byte = self.data[(bp / 8) as usize];
            let bit = (byte >> (bp % 8)) & 1;
            v |= (bit as u64) << i;
        }
        v
    }
    fn is_done(&self) -> bool {
        self.bits_left <= 0
    }
}

// ---------------------------------------------------------------------------
// FSE

#[derive(Clone)]
struct FseEntry {
    symbol: u8,
    nbits: u8,
    baseline: u16,
}

#[derive(Clone)]
struct FseTable {
    log: u32,
    entries: Vec<FseEntry>,
}

fn highbit(v: u32) -> u32 {
    31 - v.leading_zeros()
}

fn fse_build(probs: &[i16], log: u32) -> R<FseTable> {
    let size = 1usize << log;
    let mut symbols = vec![0u8; size];
    let mut high_pos = size;
    // less-than-one probabilities at the end
    for (s, &p) in probs.iter().enumerate() {
        if p == -1 {
            high_pos -= 1;
            symbols[high_pos] = s as u8;
        }
    }
    let step = (size >> 1) + (size >> 3) + 3;
    let mask = size - 1;
    let mut pos = 0usize;
    for (s, &p) in probs.iter().enumerate() {
        if p > 0 {
            for _ in 0..p {
                symbols[pos] = s as u8;
                pos = (pos + step) & mask;
                while pos >= high_pos {
                    pos = (pos + step) & mask;
                }
            }
        }
    }
    if pos != 0 {
        return e("fse table spread failed");
    }
    let mut next: Vec<u32> = probs.iter().map(|&p| if p == -1 { 1 } else { p as u32 }).collect();
    let mut entries = Vec::with_capacity(size);
    for &sym in symbols.iter() {
        let s = sym as usize;
        let ns = next[s];
        next[s] += 1;
        let nbits = log - highbit(ns);
        let baseline = ((ns as usize) << nbits).wrapping_sub(size) as u16;
        entries.push(FseEntry { symbol: sym, nbits: nbits as u8, baseline });
    }
    Ok(FseTable { log, entries })
}

/// Parse an FSE table description. Returns the table and bytes consumed.
fn fse_parse(data: &[u8], max_log: u32) -> R<(FseTable, usize)> {
    let mut br = FwdBits::new(data);
    let log = br.read(4) as u32 + 5;
    if log > max_log {
        return e("fse accuracy log too large");
    }
    let mut remaining: i32 = (1 << log) + 1;
    let mut probs: Vec<i16> = Vec::new();
    while remaining > 1 && probs.len() < 256 {
        let max_bits = 32 - (remaining as u32).leading_zeros(); // bits to represent remaining
        let low_threshold = ((1i32 << max_bits) - 1 - remaining) as u64;
        let small_mask = (1u64 << (max_bits - 1)) - 1;
        let peeked = br.peek(max_bits);
        let small = peeked & small_mask;
        let value: i32 = if small < low_threshold {
            br.pos += (max_bits - 1) as usize;
            small as i32
        } else {
            br.pos += max_bits as usize;
            let mut v = peeked;
            if v >= (1u64 << (max_bits - 1)) {
                v -= low_threshold;
            }
            v as i32
        };
        let prob = value - 1;
        if prob == -1 {
            remaining -= 1;
        } else {
            remaining -= prob;
        }
        probs.push(prob as i16);
        if prob == 0 {
            loop {
                let r = br.read(2);
                for _ in 0..r {
                    probs.push(0);
                }
                if r != 3 {
                    break;
                }
            }
        }
    }
    if remaining != 1 {
        return e("fse table description invalid");
    }
    let consumed = br.bytes_consumed();
    if consumed > data.len() {
        return e("fse table description truncated");
    }
    let table = fse_build(&probs, log)?;
    Ok((table, consumed))
}

// ---------------------------------------------------------------------------
// Huffman

#[derive(Clone)]
struct HuffTable {
    max_bits: u32,
    // indexed by max_bits bits
    entries: Vec<(u8, u8)>, // (symbol, nbits)
}

fn huff_build(weights: &[u8]) -> R<HuffTable> {
    // weights includes the final deduced weight
    let total: u32 = weights.iter().map(|&w| if w > 0 { 1u32 << (w - 1) } else { 0 }).sum();
    if total == 0 || !total.is_power_of_two() {
        return e("invalid huffman weights");
    }
    let max_bits = highbit(total);
    let size = 1usize << max_bits;
    let mut entries = vec![(0u8, 0u8); size];
    let mut pos = 0usize;
    // weights ascending (1..=max), symbols ascending
    for w in 1..=max_bits as u8 {
        let nbits = (max_bits + 1 - w as u32) as u8;
        let count = 1usize << (w - 1);
        for (s, &sw) in weights.iter().enumerate() {
            if sw == w {
                for _ in 0..count {
                    if pos >= size {
                        return e("huffman table overflow");
                    }
                    entries[pos] = (s as u8, nbits);
                    pos += 1;
                }
            }
        }
    }
    if pos != size {
        return e("huffman table incomplete");
    }
    Ok(HuffTable { max_bits, entries })
}

/// Parse a Huffman tree description. Returns the table and bytes consumed.
fn huff_parse(data: &[u8]) -> R<(HuffTable, usize)> {
    if data.is_empty() {
        return e("missing huffman header");
    }
    let hb = data[0] as usize;
    let mut weights: Vec<u8> = Vec::new();
    let consumed;
    if hb < 128 {
        // FSE compressed weights
        let csize = hb;
        if 1 + csize > data.len() {
            return e("huffman weights truncated");
        }
        let wdata = &data[1..1 + csize];
        let (table, used) = fse_parse(wdata, 6)?;
        let stream = &wdata[used..];
        let mut bits = BackBits::new(stream)?;
        let log = table.log;
        let mut s1 = bits.read(log) as usize;
        let mut s2 = bits.read(log) as usize;
        loop {
            let en = &table.entries[s1];
            weights.push(en.symbol);
            if bits.bits_left < 0 {
                break;
            }
            let nb = en.nbits as u32;
            let add = bits.read(nb) as usize;
            s1 = en.baseline as usize + add;
            if bits.bits_left < 0 && bits.bits_left + (nb as i64) < 0 {
                break;
            }
            // check end condition precisely: when all bits consumed, the final symbol decoded with 0 added bits
            let en2 = &table.entries[s2];
            weights.push(en2.symbol);
            if bits.bits_left < 0 {
                break;
            }
            let nb2 = en2.nbits as u32;
            let add2 = bits.read(nb2) as usize;
            s2 = en2.baseline as usize + add2;
            if bits.bits_left < 0 && bits.bits_left + (nb2 as i64) < 0 {
                break;
            }
            if weights.len() > 255 {
                return e("too many huffman weights");
            }
        }
        consumed = 1 + csize;
    } else {
        let n = hb - 127;
        let nbytes = (n + 1) / 2;
        if 1 + nbytes > data.len() {
            return e("huffman weights truncated");
        }
        for i in 0..n {
            let b = data[1 + i / 2];
            let w = if i % 2 == 0 { b >> 4 } else { b & 0x0f };
            weights.push(w);
        }
        consumed = 1 + nbytes;
    }
    // deduce last weight
    let partial: u32 = weights.iter().map(|&w| if w > 0 { 1u32 << (w - 1) } else { 0 }).sum();
    if partial == 0 {
        return e("invalid huffman weights");
    }
    let k = highbit(partial) + 1;
    let last_val = (1u32 << k) - partial;
    if !last_val.is_power_of_two() {
        return e("invalid huffman weights (last)");
    }
    weights.push((highbit(last_val) + 1) as u8);
    let table = huff_build(&weights)?;
    Ok((table, consumed))
}

fn huff_decode_stream(table: &HuffTable, data: &[u8], n: usize, out: &mut Vec<u8>) -> R<()> {
    let mut bits = BackBits::new(data)?;
    for _ in 0..n {
        let idx = bits.peek(table.max_bits) as usize;
        let (sym, nb) = table.entries[idx];
        out.push(sym);
        bits.bits_left -= nb as i64;
        if bits.bits_left < -(table.max_bits as i64) {
            return e("huffman stream overrun");
        }
    }
    Ok(())
}

