//! Schema tree built from the flat list of schema elements.

use super::metadata::*;

#[derive(Debug, Clone, PartialEq)]
pub enum DType {
    Null,
    Boolean,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    String,
    Binary,
    Date,
    /// time of day in nanoseconds
    Time,
    Datetime(TimeUnit, Option<String>),
    /// Int96 timestamps -> Datetime(ns)
    Decimal(i32, i32),
    List(Box<DType>),
    Struct(Vec<(String, DType)>),
}

#[derive(Debug, Clone)]
pub struct SchemaNode {
    pub name: String,
    pub element: SchemaElement,
    pub children: Vec<SchemaNode>,
    pub max_def: i16,
    pub max_rep: i16,
    /// Index into the list of leaf columns (for leaves).
    pub leaf_index: Option<usize>,
    pub path: Vec<String>,
    pub depth: usize,
}

impl SchemaNode {
    pub fn is_leaf(&self) -> bool {
        self.children.is_empty() && self.element.num_children.unwrap_or(0) == 0
    }
    pub fn repetition(&self) -> Repetition {
        self.element.repetition.unwrap_or(Repetition::Required)
    }
    pub fn is_list(&self) -> bool {
        matches!(self.element.logical_type, Some(LogicalType::List))
            || matches!(self.element.converted_type, Some(ConvertedType::List))
    }
    pub fn is_map(&self) -> bool {
        matches!(self.element.logical_type, Some(LogicalType::Map))
            || matches!(self.element.converted_type, Some(ConvertedType::Map) | Some(ConvertedType::MapKeyValue))
    }
}

#[derive(Debug, Clone)]
pub struct LeafInfo {
    pub path: Vec<String>,
    pub max_def: i16,
    pub max_rep: i16,
    pub physical_type: PhysicalType,
    pub type_length: usize,
}

pub struct Schema {
    pub root: SchemaNode,
    pub leaves: Vec<LeafInfo>,
}

pub fn build_schema(elements: &[SchemaElement]) -> Result<Schema, String> {
    if elements.is_empty() {
        return Err("empty schema".into());
    }
    let mut idx = 0usize;
    let mut leaves = Vec::new();
    let root = build_node(elements, &mut idx, 0, 0, &[], 0, &mut leaves, true)?;
    Ok(Schema { root, leaves })
}

#[allow(clippy::too_many_arguments)]
fn build_node(
    elements: &[SchemaElement],
    idx: &mut usize,
    def: i16,
    rep: i16,
    parent_path: &[String],
    depth: usize,
    leaves: &mut Vec<LeafInfo>,
    is_root: bool,
) -> Result<SchemaNode, String> {
    if *idx >= elements.len() {
        return Err("schema element index out of bounds".into());
    }
    let el = elements[*idx].clone();
    *idx += 1;
    let (mut def, mut rep) = (def, rep);
    if !is_root {
        match el.repetition.unwrap_or(Repetition::Required) {
            Repetition::Required => {}
            Repetition::Optional => def += 1,
            Repetition::Repeated => {
                def += 1;
                rep += 1;
            }
        }
    }
    let mut path = parent_path.to_vec();
    if !is_root {
        path.push(el.name.clone());
    }
    let nchildren = el.num_children.unwrap_or(0).max(0) as usize;
    let mut children = Vec::with_capacity(nchildren);
    let mut leaf_index = None;
    if nchildren == 0 && !is_root {
        if el.physical_type.is_none() {
            return Err(format!("schema element '{}' has no type", el.name));
        }
        leaf_index = Some(leaves.len());
        leaves.push(LeafInfo {
            path: path.clone(),
            max_def: def,
            max_rep: rep,
            physical_type: el.physical_type.unwrap(),
            type_length: el.type_length.unwrap_or(0).max(0) as usize,
        });
    } else {
        for _ in 0..nchildren {
            children.push(build_node(elements, idx, def, rep, &path, depth + 1, leaves, false)?);
        }
    }
    Ok(SchemaNode { name: el.name.clone(), element: el, children, max_def: def, max_rep: rep, leaf_index, path, depth })
}

/// Determine the (polars-like) data type for a node.
pub fn node_dtype(node: &SchemaNode) -> DType {
    if node.is_leaf() {
        return primitive_dtype(&node.element);
    }
    let el = &node.element;
    if node.is_list() && node.children.len() == 1 {
        let repeated = &node.children[0];
        let inner = list_element_dtype(repeated);
        return DType::List(Box::new(inner));
    }
    if node.is_map() && node.children.len() == 1 {
        let kv = &node.children[0];
        let fields: Vec<(String, DType)> = kv.children.iter().map(|c| (c.name.clone(), node_dtype(c))).collect();
        return DType::List(Box::new(DType::Struct(fields)));
    }
    let st = DType::Struct(node.children.iter().map(|c| (c.name.clone(), node_dtype(c))).collect());
    if el.repetition == Some(Repetition::Repeated) {
        // repeated group without annotation -> list of struct
        return DType::List(Box::new(st));
    }
    st
}

/// For the repeated child of a LIST group, determine the element type.
pub fn list_element_dtype(repeated: &SchemaNode) -> DType {
    if repeated.is_leaf() {
        return primitive_dtype(&repeated.element);
    }
    if is_list_element_group(repeated) {
        // 3-level: repeated group with a single child element
        node_dtype(&repeated.children[0])
    } else {
        // legacy: the repeated group itself is the element (struct)
        DType::Struct(repeated.children.iter().map(|c| (c.name.clone(), node_dtype(c))).collect())
    }
}

/// Whether a repeated node inside a LIST is the standard 3-level wrapper.
pub fn is_list_element_group(repeated: &SchemaNode) -> bool {
    if repeated.is_leaf() {
        return false;
    }
    if repeated.children.len() != 1 {
        return false;
    }
    let name = repeated.name.as_str();
    if name == "array" || name.ends_with("_tuple") {
        return false;
    }
    true
}

pub fn primitive_dtype(el: &SchemaElement) -> DType {
    let pt = match el.physical_type {
        Some(p) => p,
        None => return DType::Null,
    };
    use ConvertedType as C;
    use LogicalType as L;
    match pt {
        PhysicalType::Boolean => DType::Boolean,
        PhysicalType::Int32 => {
            if let Some(lt) = &el.logical_type {
                match lt {
                    L::Integer { bit_width: 8, is_signed: true } => return DType::Int8,
                    L::Integer { bit_width: 16, is_signed: true } => return DType::Int16,
                    L::Integer { bit_width: 32, is_signed: true } => return DType::Int32,
                    L::Integer { bit_width: 8, is_signed: false } => return DType::UInt8,
                    L::Integer { bit_width: 16, is_signed: false } => return DType::UInt16,
                    L::Integer { bit_width: 32, is_signed: false } => return DType::UInt32,
                    L::Date => return DType::Date,
                    L::Time { .. } => return DType::Time,
                    L::Decimal { scale, precision } => return DType::Decimal(*precision, *scale),
                    L::Unknown => return DType::Null,
                    _ => {}
                }
            }
            match el.converted_type {
                Some(C::Int8) => DType::Int8,
                Some(C::Int16) => DType::Int16,
                Some(C::Int32) => DType::Int32,
                Some(C::Uint8) => DType::UInt8,
                Some(C::Uint16) => DType::UInt16,
                Some(C::Uint32) => DType::UInt32,
                Some(C::Date) => DType::Date,
                Some(C::TimeMillis) => DType::Time,
                Some(C::Decimal) => DType::Decimal(el.precision.unwrap_or(0), el.scale.unwrap_or(0)),
                _ => DType::Int32,
            }
        }
        PhysicalType::Int64 => {
            if let Some(lt) = &el.logical_type {
                match lt {
                    L::Integer { bit_width: 64, is_signed: false } => return DType::UInt64,
                    L::Integer { bit_width: 64, is_signed: true } => return DType::Int64,
                    L::Timestamp { is_adjusted_to_utc, unit } => {
                        return DType::Datetime(*unit, if *is_adjusted_to_utc { Some("UTC".to_string()) } else { None })
                    }
                    L::Time { .. } => return DType::Time,
                    L::Decimal { scale, precision } => return DType::Decimal(*precision, *scale),
                    _ => {}
                }
            }
            match el.converted_type {
                Some(C::Uint64) => DType::UInt64,
                Some(C::TimestampMillis) => DType::Datetime(TimeUnit::Millis, None),
                Some(C::TimestampMicros) => DType::Datetime(TimeUnit::Micros, None),
                Some(C::TimeMicros) => DType::Time,
                Some(C::Decimal) => DType::Decimal(el.precision.unwrap_or(0), el.scale.unwrap_or(0)),
                _ => DType::Int64,
            }
        }
        PhysicalType::Int96 => DType::Datetime(TimeUnit::Nanos, None),
        PhysicalType::Float => DType::Float32,
        PhysicalType::Double => DType::Float64,
        PhysicalType::ByteArray => {
            if matches!(el.logical_type, Some(L::String) | Some(L::Enum) | Some(L::Json))
                || matches!(el.converted_type, Some(C::Utf8) | Some(C::Enum) | Some(C::Json))
            {
                DType::String
            } else {
                DType::Binary
            }
        }
        PhysicalType::FixedLenByteArray => {
            if let Some(L::Decimal { scale, precision }) = &el.logical_type {
                return DType::Decimal(*precision, *scale);
            }
            if el.converted_type == Some(C::Decimal) {
                return DType::Decimal(el.precision.unwrap_or(0), el.scale.unwrap_or(0));
            }
            if matches!(el.logical_type, Some(L::Float16)) {
                return DType::Float32;
            }
            DType::Binary
        }
    }
}

/// Whether the schema has a REPEATED group that is not a LIST/MAP element wrapper.
pub fn has_unannotated_repeated_group(node: &SchemaNode) -> bool {
    for c in &node.children {
        if check_rep(c, false) {
            return true;
        }
    }
    false
}

fn check_rep(node: &SchemaNode, parent_is_wrapper: bool) -> bool {
    if !node.is_leaf() && node.repetition() == Repetition::Repeated && !parent_is_wrapper {
        return true;
    }
    let wrapper = node.is_list() || node.is_map();
    for c in &node.children {
        if check_rep(c, wrapper) {
            return true;
        }
    }
    false
}
EOF
