                DType::String
            } else {
                DType::Binary
            }
        }
        PhysicalType::FixedLenByteArray => {
            if let Some(L::Decimal { scale, precision }) = &el.logical_type {
                return DType::Decimal(*precision, *scale);
            }
            if el.converted_type == Some(C::Decimal) {
                return DType::Decimal(el.precision.unwrap_or(0), el.scale.unwrap_or(0));
            }
            if matches!(el.logical_type, Some(L::Float16)) {
                return DType::Float32;
            }
            DType::Binary
        }
    }
}

/// Whether the schema has a REPEATED group that is not a LIST/MAP element wrapper.
pub fn has_unannotated_repeated_group(node: &SchemaNode) -> bool {
    for c in &node.children {
        if check_rep(c, false) {
            return true;
        }
    }
    false
}

fn check_rep(node: &SchemaNode, parent_is_wrapper: bool) -> bool {
    if !node.is_leaf() && node.repetition() == Repetition::Repeated && !parent_is_wrapper {
        return true;
    }
    let wrapper = node.is_list() || node.is_map();
    for c in &node.children {
        if check_rep(c, wrapper) {
            return true;
        }
    }
    false
}
