//! Row values and polars-like formatting.

use super::metadata::TimeUnit;
use super::schema::DType;
use std::fmt::Write;

#[derive(Debug, Clone)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    UInt(u64),
    F32(f32),
    F64(f64),
    Str(String),
    Bin(Vec<u8>),
    Date(i32),
    /// nanoseconds since midnight
    Time(i64),
    Datetime(i64, TimeUnit, Option<String>),
    Decimal(i128, i32),
    List(Vec<Value>),
    Struct(Vec<Value>),
}

impl Value {
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }
}

/// Mirrors polars' float formatting.
pub fn fmt_float(v: f64) -> String {
    const SCIENTIFIC_BOUND: f64 = 999999.0;
    if v.is_nan() {
        return "NaN".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    if v.fract() == 0.0 && v.abs() < SCIENTIFIC_BOUND {
        return format!("{:.1}", v);
    }
    let plain = format!("{}", v);
    if plain.len() > 9 {
        let a = v.abs();
        if !(0.000001..=SCIENTIFIC_BOUND).contains(&a) || a > SCIENTIFIC_BOUND {
            format!("{:.4e}", v)
        } else {
            let s = format!("{:.6}", v);
            if s.ends_with('0') {
                let mut s = s.as_str();
                let mut len = s.len() - 1;
                while s.ends_with('0') {
                    s = &s[..len];
                    len = len.saturating_sub(1);
                }
                s.to_string()
            } else {
                s
            }
        }
    } else {
        plain
    }
}

pub fn fmt_binary(d: &[u8]) -> String {
    let mut s = String::from("b\"");
    for &b in d {
        if b.is_ascii_graphic() {
            s.push(b as char);
        } else {
            let _ = write!(s, "\\x{:02x}", b);
        }
    }
    s.push('"');
    s
}

// --- date/time helpers

/// Civil date from days since 1970-01-01.
pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn fmt_year(y: i64) -> String {
    if (0..=9999).contains(&y) {
        format!("{:04}", y)
    } else if y < 0 {
        format!("-{:04}", -y)
    } else {
        format!("+{}", y)
    }
}

pub fn fmt_date(days: i32) -> String {
    let (y, m, d) = civil_from_days(days as i64);
    format!("{}-{:02}-{:02}", fmt_year(y), m, d)
}

fn fmt_fraction(nanos: u32) -> String {
    if nanos == 0 {
        String::new()
    } else if nanos % 1_000_000 == 0 {
        format!(".{:03}", nanos / 1_000_000)
    } else if nanos % 1_000 == 0 {
        format!(".{:06}", nanos / 1_000)
    } else {
        format!(".{:09}", nanos)
    }
}

/// Format a timestamp given seconds since epoch and nanoseconds within the second.
pub fn fmt_naive_datetime(secs: i64, nanos: u32) -> String {
    let days = secs.div_euclid(86400);
    let sod = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = sod / 3600;
    let mi = (sod % 3600) / 60;
    let s = sod % 60;
    format!("{}-{:02}-{:02} {:02}:{:02}:{:02}{}", fmt_year(y), m, d, h, mi, s, fmt_fraction(nanos))
}

pub fn fmt_datetime(v: i64, unit: TimeUnit, tz: &Option<String>) -> String {
    let (secs, nanos) = match unit {
        TimeUnit::Millis => (v.div_euclid(1000), (v.rem_euclid(1000) * 1_000_000) as u32),
        TimeUnit::Micros => (v.div_euclid(1_000_000), (v.rem_euclid(1_000_000) * 1000) as u32),
        TimeUnit::Nanos => (v.div_euclid(1_000_000_000), v.rem_euclid(1_000_000_000) as u32),
    };
    let base = fmt_naive_datetime(secs, nanos);
    match tz {
        Some(tz) => format!("{} {}", base, tz),
        None => base,
    }
}

pub fn fmt_time(nanos: i64) -> String {
    let nanos = nanos.rem_euclid(86_400_000_000_000);
    let secs = nanos / 1_000_000_000;
    let frac = (nanos % 1_000_000_000) as u32;
    format!("{:02}:{:02}:{:02}{}", secs / 3600, (secs % 3600) / 60, secs % 60, fmt_fraction(frac))
}

pub fn fmt_decimal(v: i128, scale: i32) -> String {
    let scale = scale.max(0) as usize;
    let neg = v < 0;
    let abs = v.unsigned_abs();
    let digits = abs.to_string();
    let mut s = String::new();
    if neg {
        s.push('-');
    }
    if scale == 0 {
        s.push_str(&digits);
        return s;
    }
    if digits.len() <= scale {
        s.push('0');
        s.push('.');
        for _ in 0..(scale - digits.len()) {
            s.push('0');
        }
        s.push_str(&digits);
    } else {
        let (ip, fp) = digits.split_at(digits.len() - scale);
        s.push_str(ip);
        s.push('.');
        s.push_str(fp);
    }
    s
}

/// Format a value the way polars' `AnyValue` Display does.
pub fn fmt_value(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => format!("{}", b),
        Value::Int(i) => format!("{}", i),
        Value::UInt(u) => format!("{}", u),
        Value::F32(f) => fmt_float(*f as f64),
        Value::F64(f) => fmt_float(*f),
        Value::Str(s) => format!("\"{}\"", s),
        Value::Bin(b) => fmt_binary(b),
        Value::Date(d) => fmt_date(*d),
        Value::Time(t) => fmt_time(*t),
        Value::Datetime(v, u, tz) => fmt_datetime(*v, *u, tz),
        Value::Decimal(v, s) => fmt_decimal(*v, *s),
        Value::List(items) => fmt_list(items),
        Value::Struct(fields) => {
            let mut s = String::from("{");
            for (i, f) in fields.iter().enumerate() {
                if i > 0 {
                    s.push(',');
                }
                s.push_str(&fmt_value(f));
            }
            s.push('}');
            s
        }
    }
}

fn fmt_list(items: &[Value]) -> String {
    const MAX_ITEMS: usize = 3;
    if items.is_empty() {
        return "[]".to_string();
    }
    let mut s = String::from("[");
    if MAX_ITEMS >= items.len() {
        for (i, it) in items.iter().enumerate() {
            if i > 0 {
                s.push_str(", ");
            }
            s.push_str(&fmt_value(it));
        }
    } else {
        for (i, it) in items.iter().enumerate() {
            if i == MAX_ITEMS - 1 {
                s.push_str("… ");
                s.push_str(&fmt_value(items.last().unwrap()));
                break;
            } else {
                s.push_str(&fmt_value(it));
                s.push_str(", ");
            }
        }
    }
    s.push(']');
    s
}

/// Top-level cell formatting (nulls shown as NULL).
pub fn fmt_cell(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        other => fmt_value(other),
    }
}

/// Null value for a dtype (polars Null dtype columns display as null).
pub fn dtype_is_null(dt: &DType) -> bool {
    matches!(dt, DType::Null)
}
