//! Assemble nested row values from Dremel-encoded leaf columns.

use super::decode::{ColumnData, Values};
use super::metadata::{LogicalType, PhysicalType, Repetition, TimeUnit};
use super::schema::*;
use super::value::Value;

pub struct LeafStream<'a> {
    pub data: &'a ColumnData,
    pub pos: usize,
    pub value_pos: usize,
    pub dtype: DType,
    pub physical: PhysicalType,
}

impl<'a> LeafStream<'a> {
    fn cur_def(&self) -> i16 {
        self.data.def_levels.get(self.pos).copied().unwrap_or(0)
    }
    fn cur_rep(&self) -> i16 {
        self.data.rep_levels.get(self.pos).copied().unwrap_or(0)
    }
    fn exhausted(&self) -> bool {
        self.pos >= self.data.def_levels.len()
    }
    fn take_value(&mut self) -> Value {
        let v = convert_value(&self.data.values, self.value_pos, &self.dtype, self.physical);
        self.value_pos += 1;
        v
    }
}

fn convert_value(values: &Values, idx: usize, dtype: &DType, physical: PhysicalType) -> Value {
    match values {
        Values::Bool(v) => v.get(idx).map(|b| Value::Bool(*b)).unwrap_or(Value::Null),
        Values::I32(v) => {
            let Some(&x) = v.get(idx) else { return Value::Null };
            match dtype {
                DType::Null => Value::Null,
                DType::Int8 => Value::Int(x as i8 as i64),
                DType::Int16 => Value::Int(x as i16 as i64),
                DType::UInt8 => Value::UInt(x as u8 as u64),
                DType::UInt16 => Value::UInt(x as u16 as u64),
                DType::UInt32 => Value::UInt(x as u32 as u64),
                DType::Date => Value::Date(x),
                DType::Time => Value::Time(x as i64 * 1_000_000),
                DType::Decimal(_, s) => Value::Decimal(x as i128, *s),
                _ => Value::Int(x as i64),
            }
        }
        Values::I64(v) => {
            let Some(&x) = v.get(idx) else { return Value::Null };
            match dtype {
                DType::UInt64 => Value::UInt(x as u64),
                DType::Datetime(u, tz) => Value::Datetime(x, *u, tz.clone()),
                DType::Time => {
                    // TIME_MICROS or TIME(NANOS); we don't know unit here precisely -> handled by caller via dtype
                    Value::Time(x)
                }
                DType::Decimal(_, s) => Value::Decimal(x as i128, *s),
                _ => Value::Int(x),
            }
        }
        Values::I96(v) => {
            let Some(x) = v.get(idx) else { return Value::Null };
            let nanos_of_day = (x[0] as u64 | ((x[1] as u64) << 32)) as i64;
            let julian_day = x[2] as i64;
            let days = julian_day - 2_440_588;
            let ns = days.wrapping_mul(86_400_000_000_000).wrapping_add(nanos_of_day);
            Value::Datetime(ns, TimeUnit::Nanos, None)
        }
        Values::F32(v) => v.get(idx).map(|f| Value::F32(*f)).unwrap_or(Value::Null),
        Values::F64(v) => v.get(idx).map(|f| Value::F64(*f)).unwrap_or(Value::Null),
        Values::Bytes(v) => {
            let Some(b) = v.get(idx) else { return Value::Null };
            match dtype {
                DType::String => Value::Str(String::from_utf8_lossy(b).into_owned()),
                DType::Decimal(_, s) => {
                    // big-endian two's complement
                    let mut val: i128 = 0;
                    if !b.is_empty() {
                        let neg = b[0] & 0x80 != 0;
                        val = if neg { -1 } else { 0 };
                        for &byte in b.iter() {
                            val = (val << 8) | byte as i128;
                        }
                    }
                    Value::Decimal(val, *s)
                }
                DType::Float32 if physical == PhysicalType::FixedLenByteArray && b.len() == 2 => {
                    let bits = u16::from_le_bytes([b[0], b[1]]);
                    Value::F32(f16_to_f32(bits))
                }
                _ => Value::Bin(b.clone()),
            }
        }
    }
}

fn f16_to_f32(h: u16) -> f32 {
    let sign = ((h >> 15) & 1) as u32;
    let exp = ((h >> 10) & 0x1f) as u32;
    let frac = (h & 0x3ff) as u32;
    let bits = if exp == 0 {
        if frac == 0 {
            sign << 31
        } else {
            // subnormal
            let mut e = 127 - 15 + 1;
            let mut f = frac;
            while f & 0x400 == 0 {
                f <<= 1;
                e -= 1;
            }
            f &= 0x3ff;
            (sign << 31) | ((e as u32) << 23) | (f << 13)
        }
    } else if exp == 31 {
        (sign << 31) | 0x7f80_0000 | (frac << 13)
    } else {
        (sign << 31) | ((exp + 112) << 23) | (frac << 13)
    };
    f32::from_bits(bits)
}

/// Time unit adjustments for Time dtype of INT64 leaves.
fn time_unit_multiplier(node: &SchemaNode) -> i64 {
    match &node.element.logical_type {
        Some(LogicalType::Time { unit: TimeUnit::Micros, .. }) => 1000,
        Some(LogicalType::Time { unit: TimeUnit::Nanos, .. }) => 1,
        Some(LogicalType::Time { unit: TimeUnit::Millis, .. }) => 1_000_000,
        _ => match node.element.converted_type {
            Some(super::metadata::ConvertedType::TimeMicros) => 1000,
            _ => 1,
        },
    }
}

/// Collect leaf indices under a node, in order.
fn leaf_indices(node: &SchemaNode, out: &mut Vec<usize>) {
    if let Some(i) = node.leaf_index {
        out.push(i);
    }
    for c in &node.children {
        leaf_indices(c, out);
    }
}

pub struct Assembler<'a> {
    pub streams: Vec<LeafStream<'a>>,
}

impl<'a> Assembler<'a> {
    fn first_leaf(&self, node: &SchemaNode) -> Option<usize> {
        let mut v = Vec::new();
        leaf_indices(node, &mut v);
        v.first().copied()
    }

    fn consume_one_each(&mut self, node: &SchemaNode) {
        let mut v = Vec::new();
        leaf_indices(node, &mut v);
        for i in v {
            self.streams[i].pos += 1;
        }
    }

    /// Assemble the value of `node` for the current instance (its parent instance).
    pub fn assemble(&mut self, node: &SchemaNode) -> Value {
        let rep = node.repetition();
        match rep {
            Repetition::Repeated => {
                // list of elements determined by rep levels
                let Some(li) = self.first_leaf(node) else { return Value::List(vec![]) };
                if self.streams[li].exhausted() {
                    return Value::List(vec![]);
                }
                if self.streams[li].cur_def() < node.max_def {
                    // empty list (or null handled by parent)
                    self.consume_one_each(node);
                    return Value::List(vec![]);
                }
                let mut items = Vec::new();
                loop {
                    items.push(self.assemble_defined(node));
                    // next element?
                    if self.streams[li].exhausted() {
                        break;
                    }
                    let r = self.streams[li].cur_rep();
                    if r == node.max_rep {
                        continue;
                    }
                    break;
                }
                Value::List(items)
            }
            Repetition::Optional => {
                let Some(li) = self.first_leaf(node) else { return Value::Null };
                if self.streams[li].exhausted() || self.streams[li].cur_def() < node.max_def {
                    self.consume_one_each(node);
                    return Value::Null;
                }
                self.assemble_defined(node)
            }
            Repetition::Required => self.assemble_defined(node),
        }
    }

    /// Assemble a node whose own definition level is satisfied.
    fn assemble_defined(&mut self, node: &SchemaNode) -> Value {
        if let Some(li) = node.leaf_index {
            let st = &mut self.streams[li];
            let def = st.cur_def();
            st.pos += 1;
            if def == st.data.max_def {
                let mut v = st.take_value();
                if let (Value::Time(t), PhysicalType::Int64) = (&v, st.physical) {
                    v = Value::Time(*t * time_unit_multiplier(node));
                }
                return v;
            }
            return Value::Null;
        }
        if node.is_list() && node.children.len() == 1 {
            let repeated = &node.children[0];
            // the repeated child produces the list
            let v = self.assemble_repeated_list(repeated);
            return v;
        }
        if node.is_map() && node.children.len() == 1 {
            let repeated = &node.children[0];
            return self.assemble_repeated_list_struct(repeated);
        }
        if node.repetition() == Repetition::Repeated && node.element.repetition.is_some() {
            // unannotated repeated group: element is struct of children (this call is for one element)
            let fields = node.children.iter().map(|c| self.assemble(c)).collect();
            return Value::Struct(fields);
        }
        let fields = node.children.iter().map(|c| self.assemble(c)).collect();
        Value::Struct(fields)
    }

    /// LIST semantics: `repeated` is the repeated child of a list group.
    fn assemble_repeated_list(&mut self, repeated: &SchemaNode) -> Value {
        let Some(li) = self.first_leaf(repeated) else { return Value::List(vec![]) };
        if self.streams[li].exhausted() || self.streams[li].cur_def() < repeated.max_def {
            self.consume_one_each(repeated);
            return Value::List(vec![]);
        }
        let mut items = Vec::new();
        loop {
            let item = if repeated.is_leaf() {
                self.assemble_defined(repeated)
            } else if is_list_element_group(repeated) {
                self.assemble(&repeated.children[0])
            } else {
                let fields = repeated.children.iter().map(|c| self.assemble(c)).collect();
                Value::Struct(fields)
            };
            items.push(item);
            if self.streams[li].exhausted() {
                break;
            }
            if self.streams[li].cur_rep() == repeated.max_rep {
                continue;
            }
            break;
        }
        Value::List(items)
    }

    /// MAP semantics: repeated key_value group -> list of struct{key,value}.
    fn assemble_repeated_list_struct(&mut self, repeated: &SchemaNode) -> Value {
        let Some(li) = self.first_leaf(repeated) else { return Value::List(vec![]) };
        if self.streams[li].exhausted() || self.streams[li].cur_def() < repeated.max_def {
            self.consume_one_each(repeated);
            return Value::List(vec![]);
        }
        let mut items = Vec::new();
        loop {
            let fields = repeated.children.iter().map(|c| self.assemble(c)).collect();
            items.push(Value::Struct(fields));
            if self.streams[li].exhausted() {
                break;
            }
            if self.streams[li].cur_rep() == repeated.max_rep {
                continue;
            }
            break;
        }
        Value::List(items)
    }
}

/// Assemble up to `max_rows` rows for a top-level column node.
pub fn assemble_column(node: &SchemaNode, streams: Vec<LeafStream>, max_rows: usize) -> Vec<Value> {
    let mut asm = Assembler { streams };
    let mut rows = Vec::new();
    let mut leaf_idx = Vec::new();
    leaf_indices(node, &mut leaf_idx);
    if leaf_idx.is_empty() {
        return rows;
    }
    while rows.len() < max_rows {
        let first = leaf_idx[0];
        if asm.streams[first].exhausted() {
            break;
        }
        // a repeated top-level node is a list
        let v = asm.assemble(node);
        rows.push(v);
    }
    rows
}
