//! High level parquet file access.

use super::assemble::{assemble_column, LeafStream};
use super::decode::{ColumnChunkReader, ColumnData, DecodeError, PageInfo};
use super::metadata::*;
use super::schema::*;
use super::value::Value;

pub const ROW_LIMIT: usize = 200;

#[derive(Debug)]
pub enum FileError {
    /// Produced when reading metadata; formatted as "Parquet error: {msg}".
    Parquet(String),
    /// Produced when reading data; formatted as "parquet: {msg}".
    Polars(String),
    Io(std::io::Error),
}

impl std::fmt::Display for FileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FileError::Parquet(m) => write!(f, "Parquet error: {}", m),
            FileError::Polars(m) => write!(f, "parquet: {}", m),
            FileError::Io(e) => write!(f, "{}", e),
        }
    }
}

pub struct ParquetFile {
    pub bytes: Vec<u8>,
    pub metadata: FileMetaData,
    pub schema: Schema,
}

pub struct Table {
    pub names: Vec<String>,
    pub columns: Vec<Vec<Value>>,
    pub num_rows: usize,
}

impl ParquetFile {
    pub fn open(path: &str) -> Result<ParquetFile, FileError> {
        let bytes = std::fs::read(path).map_err(FileError::Io)?;
        let n = bytes.len();
        if n < 12 {
            return Err(FileError::Parquet("Invalid Parquet file. Size is smaller than footer".into()));
        }
        let magic = &bytes[n - 4..];
        if magic == b"PARE" {
            return Err(FileError::Parquet(
                "Parquet file has an encrypted footer but the encryption feature is disabled".into(),
            ));
        }
        if magic != b"PAR1" {
            return Err(FileError::Parquet("Invalid Parquet file. Corrupt footer".into()));
        }
        let len = u32::from_le_bytes([bytes[n - 8], bytes[n - 7], bytes[n - 6], bytes[n - 5]]) as usize;
        if len + 8 > n {
            return Err(FileError::Parquet(format!(
                "Invalid Parquet file. Reported metadata length of {} + 8 byte footer, but file is only {} bytes",
                len, n
            )));
        }
        let footer = &bytes[n - 8 - len..n - 8];
        let metadata = parse_file_metadata(footer).map_err(|e| match e {
            ParseError::General(m) => FileError::Parquet(m),
        })?;
        let schema = build_schema(&metadata.schema).map_err(FileError::Parquet)?;
        Ok(ParquetFile { bytes, metadata, schema })
    }

    pub fn num_leaf_columns(&self) -> usize {
        self.schema.leaves.len()
    }

    /// Page information for a column chunk.
    pub fn page_infos(&self, rg: usize, col: usize) -> Vec<PageInfo> {
        let Some(rgm) = self.metadata.row_groups.get(rg) else { return vec![] };
        let Some(cc) = rgm.columns.get(col) else { return vec![] };
        let Some(md) = cc.meta_data.as_ref() else { return vec![] };
        let leaf = match self.schema.leaves.get(col) {
            Some(l) => l,
            None => return vec![],
        };
        let reader = ColumnChunkReader {
            file: &self.bytes,
            meta: md,
            type_length: leaf.type_length,
            max_def: leaf.max_def,
            max_rep: leaf.max_rep,
        };
        reader.page_infos().unwrap_or_default()
    }

    /// Read the first `ROW_LIMIT` rows of the file.
    pub fn read_table(&self) -> Result<Table, FileError> {
        let root = &self.schema.root;
        let names: Vec<String> = root.children.iter().map(|c| c.name.clone()).collect();
        let mut columns: Vec<Vec<Value>> = vec![Vec::new(); names.len()];
        if has_unannotated_repeated_group(root) {
            return Ok(Table { names, columns, num_rows: 0 });
        }
        let nleaves = self.schema.leaves.len();
        let mut rows_total = 0usize;
        for rg in &self.metadata.row_groups {
            if rows_total >= ROW_LIMIT {
                break;
            }
            let need = ROW_LIMIT - rows_total;
            // decode all leaves of this row group
            let mut datas: Vec<ColumnData> = Vec::with_capacity(nleaves);
            for (i, leaf) in self.schema.leaves.iter().enumerate() {
                let cc = rg.columns.get(i).ok_or_else(|| FileError::Polars("File out of specification: missing column chunk".into()))?;
                let md = cc
                    .meta_data
                    .as_ref()
                    .ok_or_else(|| FileError::Polars("File out of specification: missing column metadata".into()))?;
                let reader = ColumnChunkReader {
                    file: &self.bytes,
                    meta: md,
                    type_length: leaf.type_length,
                    max_def: leaf.max_def,
                    max_rep: leaf.max_rep,
                };
                let data = reader.read(Some(need)).map_err(|DecodeError(m)| FileError::Polars(m))?;
                datas.push(data);
            }
            let rg_rows = rg.num_rows.max(0) as usize;
            let take = need.min(rg_rows);
            for (ci, node) in root.children.iter().enumerate() {
                let streams: Vec<LeafStream> = self
                    .schema
                    .leaves
                    .iter()
                    .enumerate()
                    .map(|(li, leaf)| LeafStream {
                        data: &datas[li],
                        pos: 0,
                        value_pos: 0,
                        dtype: leaf_dtype(root, li),
                        physical: leaf.physical_type,
                    })
                    .collect();
                let mut vals = assemble_column(node, streams, take);
                // pad with nulls if the column produced fewer rows than expected
                while vals.len() < take {
                    vals.push(Value::Null);
                }
                columns[ci].extend(vals);
            }
            rows_total += take;
        }
        Ok(Table { names, columns, num_rows: rows_total })
    }
}

fn find_leaf<'a>(node: &'a SchemaNode, li: usize) -> Option<&'a SchemaNode> {
    if node.leaf_index == Some(li) {
        return Some(node);
    }
    for c in &node.children {
        if let Some(n) = find_leaf(c, li) {
            return Some(n);
        }
    }
    None
}

fn leaf_dtype(root: &SchemaNode, li: usize) -> DType {
    match find_leaf(root, li) {
        Some(n) => primitive_dtype(&n.element),
        None => DType::Null,
    }
}
