//! Formatting helpers.

use unicode_width::UnicodeWidthStr;

/// "1,234,567"
pub fn thousands(n: i64) -> String {
    let neg = n < 0;
    let s = n.unsigned_abs().to_string();
    let mut out = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    if neg {
        format!("-{}", out)
    } else {
        out
    }
}

/// "671 B", "2.64 KiB", "1.50 MiB"
pub fn fmt_bytes_kib(n: i64) -> String {
    let f = n as f64;
    if n < 1024 {
        format!("{} B", n)
    } else if f < 1024.0 * 1024.0 {
        format!("{:.2} KiB", f / 1024.0)
    } else if f < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.2} MiB", f / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", f / (1024.0 * 1024.0 * 1024.0))
    }
}

/// "73 B", "36.5 KB", "1.2 MB"
pub fn fmt_bytes_kb(n: i64) -> String {
    let f = n as f64;
    if n < 1024 {
        format!("{} B", n)
    } else if f < 1024.0 * 1024.0 {
        format!("{:.1} KB", f / 1024.0)
    } else if f < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.1} MB", f / (1024.0 * 1024.0))
    } else {
        format!("{:.1} GB", f / (1024.0 * 1024.0 * 1024.0))
    }
}

/// Chart axis label: "755", "4.1K", "355.5K", "1.2M"
pub fn fmt_axis_bytes(v: f64) -> String {
    if v < 1024.0 {
        format!("{:.0}", v)
    } else if v < 1024.0 * 1024.0 {
        format!("{:.1}K", v / 1024.0)
    } else if v < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.1}M", v / (1024.0 * 1024.0))
    } else {
        format!("{:.1}G", v / (1024.0 * 1024.0 * 1024.0))
    }
}

pub fn ratio(unc: i64, comp: i64) -> f64 {
    if comp == 0 {
        0.0
    } else {
        unc as f64 / comp as f64
    }
}

/// Truncate a string to `max` display columns, appending "…" when truncated
/// (the result including the ellipsis is `max` wide).
pub fn truncate_ellipsis(s: &str, max: usize) -> String {
    if s.width() <= max {
        return s.to_string();
    }
    let mut out = String::new();
    let mut w = 0;
    for c in s.chars() {
        let cw = unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
        if w + cw > max.saturating_sub(1) {
            break;
        }
        out.push(c);
        w += cw;
    }
    out.push('…');
    out
}

pub fn display_width(s: &str) -> usize {
    s.width()
}

pub fn hex_upper(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len() * 2);
    for x in b {
        s.push_str(&format!("{:02X}", x));
    }
    s
}

pub fn hex_lower(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len() * 2);
    for x in b {
        s.push_str(&format!("{:02x}", x));
    }
    s
}
