//! Application state.

use crate::parquet::file::{FileError, ParquetFile, Table};
use crate::parquet::metadata::*;
use crate::parquet::schema::SchemaNode;
use crate::parquet::value::fmt_cell;
use crate::util::*;

pub const CELL_MAX: usize = 25;
pub const MIN_COL_WIDTH: usize = 10;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    pub fn index(self) -> usize {
        match self {
            Tab::Visualize => 0,
            Tab::Metadata => 1,
            Tab::Schema => 2,
            Tab::RowGroups => 3,
        }
    }
    pub fn from_index(i: usize) -> Tab {
        match i % 4 {
            0 => Tab::Visualize,
            1 => Tab::Metadata,
            2 => Tab::Schema,
            _ => Tab::RowGroups,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TreeKind {
    Root,
    Group,
    Leaf,
}

#[derive(Clone, Debug)]
pub struct TreeItem {
    pub label: String,
    pub kind: TreeKind,
    pub leaf_index: Option<usize>,
    pub repetition: Option<Repetition>,
    pub physical: Option<PhysicalType>,
}

pub struct VizColumn {
    pub name: String,
    pub cells: Vec<String>,
    pub width: usize,
}

pub struct App {
    pub path: String,
    pub file: ParquetFile,
    pub tab: Tab,
    // visualize
    pub viz_columns: Vec<VizColumn>,
    pub num_rows: usize,
    pub selected_row: usize,
    pub row_offset: usize,
    pub col_offset: usize,
    // schema / row groups tree
    pub tree: Vec<TreeItem>,
    pub tree_selected: usize,
    pub tree_offset: usize,
    pub stats_col_offset: usize,
    pub rg_tree_selected: usize,
    pub rg_tree_offset: usize,
    pub rg_index: usize,
    pub should_quit: bool,
}

pub fn load(path: &str) -> Result<App, FileError> {
    let file = ParquetFile::open(path)?;
    let table = file.read_table()?;
    let viz_columns = build_viz_columns(&table);
    let mut tree = Vec::new();
    build_tree(&file.schema.root, "", true, true, &mut tree);
    Ok(App {
        path: path.to_string(),
        file,
        tab: Tab::Visualize,
        viz_columns,
        num_rows: table.num_rows,
        selected_row: 0,
        row_offset: 0,
        col_offset: 0,
        tree,
        tree_selected: 0,
        tree_offset: 0,
        stats_col_offset: 0,
        rg_tree_selected: 0,
        rg_tree_offset: 0,
        rg_index: 0,
        should_quit: false,
    })
}

fn build_viz_columns(table: &Table) -> Vec<VizColumn> {
    let mut out = Vec::new();
    for (ci, name) in table.names.iter().enumerate() {
        let cells: Vec<String> =
            table.columns[ci].iter().map(|v| truncate_ellipsis(&fmt_cell(v), CELL_MAX)).collect();
        let mut w = display_width(name);
        for c in &cells {
            w = w.max(display_width(c));
        }
        let width = (w + 2).max(MIN_COL_WIDTH);
        out.push(VizColumn { name: name.clone(), cells, width });
    }
    out
}

fn build_tree(node: &SchemaNode, prefix: &str, is_last: bool, is_root: bool, out: &mut Vec<TreeItem>) {
    let conn = if is_last { "└─ " } else { "├─ " };
    let name = if is_root { "root".to_string() } else { node.name.clone() };
    let label = format!("{}{}{}", prefix, conn, name);
    let kind = if is_root {
        TreeKind::Root
    } else if node.is_leaf() {
        TreeKind::Leaf
    } else {
        TreeKind::Group
    };
    out.push(TreeItem {
        label,
        kind,
        leaf_index: node.leaf_index,
        repetition: node.element.repetition,
        physical: node.element.physical_type,
    });
    let child_prefix = format!("{}{}", prefix, if is_last { "   " } else { "│  " });
    let n = node.children.len();
    for (i, c) in node.children.iter().enumerate() {
        build_tree(c, &child_prefix, i + 1 == n, false, out);
    }
}

impl App {
    pub fn metadata(&self) -> &FileMetaData {
        &self.file.metadata
    }

    pub fn num_row_groups(&self) -> usize {
        self.file.metadata.row_groups.len()
    }

    pub fn reset_nav(&mut self) {
        self.selected_row = 0;
        self.row_offset = 0;
        self.col_offset = 0;
        self.tree_selected = 0;
        self.tree_offset = 0;
        self.stats_col_offset = 0;
        self.rg_tree_selected = 0;
        self.rg_tree_offset = 0;
        self.rg_index = 0;
    }

    pub fn next_tab(&mut self) {
        self.tab = Tab::from_index(self.tab.index() + 1);
        self.reset_nav();
    }

    pub fn prev_tab(&mut self) {
        self.tab = Tab::from_index(self.tab.index() + 3);
        self.reset_nav();
    }

    // --- visualize navigation
    pub fn viz_down(&mut self, n: usize) {
        if self.num_rows == 0 {
            return;
        }
        self.selected_row = (self.selected_row + n).min(self.num_rows - 1);
    }
    pub fn viz_up(&mut self, n: usize) {
        self.selected_row = self.selected_row.saturating_sub(n);
    }
    pub fn viz_right(&mut self) {
        if self.viz_columns.is_empty() {
            return;
        }
        self.col_offset = (self.col_offset + 1).min(self.viz_columns.len() - 1);
    }
    pub fn viz_left(&mut self) {
        self.col_offset = self.col_offset.saturating_sub(1);
    }

    // --- tree navigation
    pub fn tree_down(&mut self) {
        if self.tree.is_empty() {
            return;
        }
        self.tree_selected = (self.tree_selected + 1).min(self.tree.len() - 1);
    }
    pub fn tree_up(&mut self) {
        self.tree_selected = self.tree_selected.saturating_sub(1);
    }
    pub fn rg_tree_down(&mut self) {
        if self.tree.is_empty() {
            return;
        }
        self.rg_tree_selected = (self.rg_tree_selected + 1).min(self.tree.len() - 1);
    }
    pub fn rg_tree_up(&mut self) {
        self.rg_tree_selected = self.rg_tree_selected.saturating_sub(1);
    }
    pub fn stats_right(&mut self) {
        self.stats_col_offset = (self.stats_col_offset + 1).min(9);
    }
    pub fn stats_left(&mut self) {
        self.stats_col_offset = self.stats_col_offset.saturating_sub(1);
    }
    pub fn rg_next(&mut self) {
        let n = self.num_row_groups();
        if n == 0 {
            return;
        }
        self.rg_index = (self.rg_index + 1).min(n - 1);
    }
    pub fn rg_prev(&mut self) {
        self.rg_index = self.rg_index.saturating_sub(1);
    }
}
