use crate::app::App;
use crate::parquet::metadata::*;
use crate::util::*;
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Borders};
use ratatui::Frame;
use std::collections::BTreeMap;

pub struct MetaLine {
    pub label: &'static str,
    pub value: String,
}

pub fn metadata_lines(app: &App) -> Vec<MetaLine> {
    let md = app.metadata();
    let mut raw: i64 = 0;
    let mut comp: i64 = 0;
    let mut codecs: BTreeMap<Compression, usize> = BTreeMap::new();
    let mut encodings: Vec<Encoding> = Vec::new();
    for rg in &md.row_groups {
        for cc in &rg.columns {
            if let Some(m) = &cc.meta_data {
                raw += m.total_uncompressed_size;
                comp += m.total_compressed_size;
                *codecs.entry(m.codec).or_insert(0) += 1;
                for e in &m.encodings {
                    if !encodings.contains(e) {
                        encodings.push(*e);
                    }
                }
            }
        }
    }
    let mut enc_names: Vec<&str> = encodings.iter().map(|e| e.name()).collect();
    enc_names.sort();
    let codec_str = codecs.iter().map(|(c, n)| format!("{}({})", c.display(), n)).collect::<Vec<_>>().join(", ");
    let ratio_str = if comp > 0 { format!("{:.2}x", raw as f64 / comp as f64) } else { "0.00x".to_string() };
    let avg = if md.num_rows > 0 { raw / md.num_rows } else { 0 };
    vec![
        MetaLine { label: "Format version", value: format!("{}", md.version) },
        MetaLine { label: "Created by", value: md.created_by.clone().unwrap_or_else(|| "—".to_string()) },
        MetaLine { label: "Rows", value: thousands(md.num_rows) },
        MetaLine { label: "Columns", value: format!("{}", app.file.schema.leaves.len()) },
        MetaLine { label: "Row groups", value: format!("{}", md.row_groups.len()) },
        MetaLine { label: "Size (raw)", value: fmt_bytes_kib(raw) },
        MetaLine { label: "Size (compressed)", value: fmt_bytes_kib(comp) },
        MetaLine { label: "Compression ratio", value: ratio_str },
        MetaLine { label: "Codecs (cols)", value: codec_str },
        MetaLine { label: "Encodings", value: enc_names.join(", ") },
        MetaLine { label: "Avg row size", value: format!("{} B", avg) },
    ]
}

pub fn draw(frame: &mut Frame, app: &App, area: Rect) {
    let lines = metadata_lines(app);
    let max_val = lines.iter().map(|l| display_width(&l.value)).max().unwrap_or(0);
    let box_w = (max_val + 23) as u16;
    let box_h = (lines.len() + 2) as u16;

    // horizontal placement
    let (x, w) = if box_w < area.width {
        (area.x + (area.width - box_w) / 2 + 1, box_w)
    } else if box_w == area.width {
        (area.x + 1, area.width.saturating_sub(1))
    } else {
        (area.x, area.width)
    };
    // vertical placement (the box may extend one row into the footer)
    let (y, h) = if box_h < area.height {
        (area.y + (area.height - box_h) / 2 + 1, box_h)
    } else if box_h == area.height {
        (area.y + 1, box_h)
    } else {
        (area.y, box_h.min(area.height + 1))
    };
    let rect = Rect::new(x, y, w, h);
    let title = Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD));
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Line::from(title).centered());
    let buf = frame.buffer_mut();
    let clipped = rect.intersection(buf.area);
    if clipped.width == 0 || clipped.height == 0 {
        return;
    }
    // render block in the (possibly clipped) rect
    ratatui::widgets::Widget::render(block, clipped.union(Rect::new(rect.x, rect.y, rect.width.min(clipped.width), rect.height.min(clipped.height))), buf);
    let label_style = Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD);
    for (i, l) in lines.iter().enumerate() {
        let ly = rect.y + 1 + i as u16;
        if ly >= buf.area.bottom() {
            break;
        }
        let lx = rect.x + 1;
        if lx >= buf.area.right() {
            break;
        }
        let label = format!("{:>18}", l.label);
        let (nx, _) = buf.set_stringn(lx, ly, &label, usize::MAX, label_style);
        if nx < buf.area.right() {
            let (nx2, _) = buf.set_stringn(nx, ly, " ", usize::MAX, Style::default());
            if nx2 < buf.area.right() {
                buf.set_stringn(nx2, ly, &l.value, usize::MAX, Style::default());
            }
        }
    }
}
