fn handle_key(app: &mut app::App, code: KeyCode) {
    use app::Tab;
    match code {
        KeyCode::Char('q') | KeyCode::Char('Q') => app.should_quit = true,
        KeyCode::Tab => app.next_tab(),
        KeyCode::BackTab => app.prev_tab(),
        _ => match app.tab {
            Tab::Visualize => match code {
                KeyCode::Down => app.viz_down(1),
                KeyCode::Up => app.viz_up(1),
                KeyCode::Right => app.viz_right(),
                KeyCode::Left => app.viz_left(),
                KeyCode::Char('d') => app.viz_down(app.page_size),
                KeyCode::Char('u') => app.viz_up(app.page_size),
                _ => {}
            },
            Tab::Metadata => {}
            Tab::Schema => match code {
                KeyCode::Down => app.tree_down(),
                KeyCode::Up => app.tree_up(),
                KeyCode::Right => app.stats_right(),
                KeyCode::Left => app.stats_left(),
                _ => {}
            },
            Tab::RowGroups => match code {
                KeyCode::Down => app.rg_tree_down(),
                KeyCode::Up => app.rg_tree_up(),
                KeyCode::Right => app.rg_next(),
                KeyCode::Left => app.rg_prev(),
                _ => {}
            },
        },
    }
}

fn dump(path: &str) {
    let f = match ParquetFile::open(path) {
        Ok(f) => f,
        Err(e) => {
            println!("ERROR: {}", e);
            return;
        }
    };
    println!("version {} rows {} created_by {:?}", f.metadata.version, f.metadata.num_rows, f.metadata.created_by);
    for (i, l) in f.schema.leaves.iter().enumerate() {
        println!("leaf {} {:?} def {} rep {} {:?}", i, l.path, l.max_def, l.max_rep, l.physical_type);
    }
    match f.read_table() {
        Ok(t) => {
            println!("rows {}", t.num_rows);
            println!("{}", t.names.join(" | "));
            for r in 0..t.num_rows.min(12) {
                let cells: Vec<String> = t.columns.iter().map(|c| fmt_cell(&c[r])).collect();
                println!("{}", cells.join(" | "));
            }
        }
        Err(e) => println!("READ ERROR: {}", e),
    }
    for (ci, _) in f.metadata.row_groups[0].columns.iter().enumerate().take(3) {
        let pages = f.page_infos(0, ci);
        for p in pages.iter().take(4) {
            println!("page {:?} unc {} comp {} n {} enc {:?}", p.page_type, p.uncompressed_size, p.compressed_size, p.num_values, p.encoding);
        }
    }
}

