use crate::app::{App, TreeItem, TreeKind};
use crate::parquet::metadata::*;
use crate::util::*;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{
    Block, BorderType, Borders, Cell, List, ListItem, ListState, Row, Scrollbar, ScrollbarOrientation, ScrollbarState,
    StatefulWidget, Table, TableState,
};
use ratatui::Frame;

pub const STATS_HEADERS: [&str; 10] =
    ["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];

/// Format a statistics min/max value for the schema stats table.
pub fn fmt_stat_schema(pt: PhysicalType, bytes: Option<&Vec<u8>>) -> String {
    let Some(b) = bytes else { return "NULL".to_string() };
    match pt {
        PhysicalType::Boolean => hex_lower(b),
        PhysicalType::Int32 => {
            if b.len() >= 4 {
                format!("{}", i32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            } else {
                "NULL".to_string()
            }
        }
        PhysicalType::Int64 => {
            if b.len() >= 8 {
                let mut a = [0u8; 8];
                a.copy_from_slice(&b[..8]);
                format!("{}", i64::from_le_bytes(a))
            } else {
                "NULL".to_string()
            }
        }
        PhysicalType::Int96 => "NULL".to_string(),
        PhysicalType::Float => {
            if b.len() >= 4 {
                format!("{:.4}", f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            } else {
                "NULL".to_string()
            }
        }
        PhysicalType::Double => {
            if b.len() >= 8 {
                let mut a = [0u8; 8];
                a.copy_from_slice(&b[..8]);
                format!("{:.4}", f64::from_le_bytes(a))
            } else {
                "NULL".to_string()
            }
        }
        PhysicalType::ByteArray | PhysicalType::FixedLenByteArray => match std::str::from_utf8(b) {
            Ok(s) => s.to_string(),
            Err(_) => hex_upper(b),
        },
    }
}

pub struct StatsRow {
    pub cells: Vec<String>,
    pub is_group: bool,
}

pub fn stats_rows(app: &App) -> Vec<StatsRow> {
    let md = app.metadata();
    let mut rows = Vec::new();
    for item in app.tree.iter().skip(1) {
        let rep = item.repetition.map(|r| r.name().to_string()).unwrap_or_default();
        match item.kind {
            TreeKind::Group | TreeKind::Root => {
                let mut cells = vec![rep, "group".to_string()];
                cells.resize(10, String::new());
                rows.push(StatsRow { cells, is_group: true });
            }
            TreeKind::Leaf => {
                let li = item.leaf_index.unwrap_or(0);
                let pt = item.physical.unwrap_or(PhysicalType::Boolean);
                let mut comp = 0i64;
                let mut unc = 0i64;
                let mut encodings: Vec<Encoding> = Vec::new();
                let mut codec: Option<Compression> = None;
                let mut stats: Option<&Statistics> = None;
                let mut nulls: i64 = 0;
                for rg in &md.row_groups {
                    if let Some(cc) = rg.columns.get(li) {
                        if let Some(m) = &cc.meta_data {
                            comp += m.total_compressed_size;
                            unc += m.total_uncompressed_size;
                            for e in &m.encodings {
                                if !encodings.contains(e) {
                                    encodings.push(*e);
                                }
                            }
                            if codec.is_none() {
                                codec = Some(m.codec);
                            }
                            if let Some(s) = &m.statistics {
                                if stats.is_none() {
                                    stats = Some(s);
                                }
                                nulls += s.null_count.unwrap_or(0);
                            }
                        }
                    }
                }
                let ratio_s = format!("{:.2}x", ratio(unc, comp));
                let enc_s = encodings.iter().map(|e| e.name()).collect::<Vec<_>>().join(", ");
                let codec_s = codec.map(|c| c.display()).unwrap_or_default();
                let (min_s, max_s) = match stats {
                    Some(s) => (fmt_stat_schema(pt, s.min_bytes()), fmt_stat_schema(pt, s.max_bytes())),
                    None => ("NULL".to_string(), "NULL".to_string()),
                };
                let cells = vec![
                    rep,
                    pt.name().to_string(),
                    fmt_bytes_kb(comp),
                    fmt_bytes_kb(unc),
                    ratio_s,
                    enc_s,
                    codec_s,
                    min_s,
                    max_s,
                    format!("{}", nulls),
                ];
                rows.push(StatsRow { cells, is_group: false });
            }
        }
    }
    rows
}

pub fn tree_item_style(item: &TreeItem) -> Style {
    match item.kind {
        TreeKind::Root => Style::default().fg(Color::LightYellow),
        TreeKind::Group => Style::default().fg(Color::Green),
        TreeKind::Leaf => Style::default().fg(Color::White),
    }
}

/// Renders the schema tree block (and scrollbar if needed). Returns the remaining area to the right.
pub fn render_tree(
    frame: &mut Frame,
    app: &App,
    area: Rect,
    tree_width: u16,
    selected: usize,
    offset: &mut usize,
    show_selected_legend: bool,
) -> Rect {
    let inner_h = area.height.saturating_sub(2) as usize;
    let needs_scroll = app.tree.len() > inner_h && inner_h > 0;
    let (tree_area, scroll_area, rest) = if needs_scroll {
        let [a, b, c] =
            Layout::horizontal([Constraint::Length(tree_width), Constraint::Length(1), Constraint::Min(0)]).areas(area);
        (a, Some(b), c)
    } else {
        let [a, c] = Layout::horizontal([Constraint::Length(tree_width), Constraint::Min(0)]).areas(area);
        (a, None, c)
    };
    let mut legend = vec![
        Span::styled("Leaf", Style::default().fg(Color::White)),
        Span::raw(", "),
        Span::styled("Group", Style::default().fg(Color::Green)),
    ];
    if show_selected_legend {
        legend.push(Span::raw(", "));
        legend.push(Span::styled("Selected", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    }
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Line::from(Span::styled("Schema Tree", super::bold_yellow())).centered())
        .title_bottom(Line::from(legend).centered());
    let items: Vec<ListItem> =
        app.tree.iter().map(|t| ListItem::new(Line::from(t.label.clone())).style(tree_item_style(t))).collect();
    let list = List::new(items).block(block).highlight_style(super::selected_style());
    let mut state = ListState::default().with_offset(*offset);
    if selected > 0 {
        state.select(Some(selected));
    }
    StatefulWidget::render(list, tree_area, frame.buffer_mut(), &mut state);
    *offset = state.offset();
    if let Some(sa) = scroll_area {
        let mut sstate = ScrollbarState::new(app.tree.len()).position(*offset).viewport_content_length(inner_h);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight)
            .begin_symbol(None)
            .end_symbol(None)
            .track_symbol(Some("│"))
            .track_style(Style::default().fg(Color::Yellow))
            .thumb_symbol("█")
            .thumb_style(Style::default().fg(Color::Gray));
        StatefulWidget::render(sb, sa, frame.buffer_mut(), &mut sstate);
    }
    rest
}

pub fn draw(frame: &mut Frame, app: &mut App, area: Rect) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let tw = super::tree_width(app);
    let selected = app.tree_selected;
    let mut offset = app.tree_offset;
    let rest = render_tree(frame, app, area, tw, selected, &mut offset, false);
    app.tree_offset = offset;

    // stats table
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Line::from(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))).centered());
    let inner = block.inner(rest);
    frame.render_widget(block, rest);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let rows = stats_rows(app);
    // natural widths
    let mut widths: Vec<usize> = STATS_HEADERS.iter().map(|h| h.len()).collect();
    for r in &rows {
        for (i, c) in r.cells.iter().enumerate() {
            widths[i] = widths[i].max(c.len());
        }
    }
    let widths: Vec<u16> = widths.iter().map(|w| (w.min(&30) + 1) as u16).collect();
    let visible = ((inner.width as usize).saturating_sub(2) / 12).max(1).min(10);
    let max_off = 10 - visible;
    let start = app.stats_col_offset.min(max_off);
    let cols = start..start + visible;
    let header = Row::new(
        cols.clone().map(|i| Cell::from(Span::styled(STATS_HEADERS[i], super::bold_yellow()))).collect::<Vec<_>>(),
    );
    let trows: Vec<Row> = rows
        .iter()
        .map(|r| {
            Row::new(
                cols.clone()
                    .map(|i| {
                        if r.is_group {
                            Cell::from(Span::styled(r.cells[i].clone(), Style::default().fg(Color::Green)))
                        } else {
                            Cell::from(Line::from(r.cells[i].clone()))
                        }
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .collect();
    let constraints: Vec<Constraint> = cols.clone().map(|i| Constraint::Length(widths[i])).collect();
    let table = Table::new(trows, constraints)
        .header(header)
        .column_spacing(1)
        .row_highlight_style(super::selected_style());
    let mut tstate = TableState::default().with_offset(app.tree_offset);
    if selected > 0 {
        tstate.select(Some(selected - 1));
    }
    StatefulWidget::render(table, inner, frame.buffer_mut(), &mut tstate);
}
