    let tw = super::tree_width(app);
    let selected = app.tree_selected;
    let mut offset = app.tree_offset;
    let rest = render_tree(frame, app, area, tw, selected, &mut offset, false);
    app.tree_offset = offset;

    // stats table
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(Line::from(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))).centered());
    let inner = block.inner(rest);
    frame.render_widget(block, rest);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let rows = stats_rows(app);
    // natural widths
    let mut widths: Vec<usize> = STATS_HEADERS.iter().map(|h| h.len()).collect();
    for r in &rows {
        for (i, c) in r.cells.iter().enumerate() {
            widths[i] = widths[i].max(c.len());
        }
    }
    let widths: Vec<u16> = widths.iter().map(|w| (w.min(&30) + 1) as u16).collect();
    let visible = ((inner.width as usize).saturating_sub(2) / 12).max(1).min(10);
    let max_off = 10 - visible;
    let start = app.stats_col_offset.min(max_off);
    let cols = start..start + visible;
    let header = Row::new(
        cols.clone().map(|i| Cell::from(Span::styled(STATS_HEADERS[i], super::bold_yellow()))).collect::<Vec<_>>(),
    );
    let trows: Vec<Row> = rows
        .iter()
        .map(|r| {
            Row::new(
                cols.clone()
                    .map(|i| {
                        if r.is_group {
                            Cell::from(Span::styled(r.cells[i].clone(), Style::default().fg(Color::Green)))
                        } else {
                            Cell::from(Line::from(r.cells[i].clone()))
                        }
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .collect();
    let constraints: Vec<Constraint> = cols.clone().map(|i| Constraint::Length(widths[i])).collect();
    let table = Table::new(trows, constraints)
        .header(header)
        .column_spacing(1)
        .row_highlight_style(super::selected_style());
    let mut tstate = TableState::default().with_offset(app.tree_offset);
    if selected > 0 {
        tstate.select(Some(selected - 1));
    }
    StatefulWidget::render(table, inner, frame.buffer_mut(), &mut tstate);
}
