use crate::app::{App, TreeKind};
use crate::parquet::metadata::*;
use crate::util::*;
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::symbols;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Axis, Block, Borders, Cell, Chart, Dataset, GraphType, Paragraph, Row, Table};
use ratatui::Frame;

pub fn draw(frame: &mut Frame, app: &mut App, area: Rect) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let schema_tw = super::tree_width(app);
    let inner_h = area.height.saturating_sub(2) as usize;
    let needs_scroll = app.tree.len() > inner_h && inner_h > 0;
    let tw = if needs_scroll { schema_tw } else { schema_tw.saturating_sub(1) };
    let selected = app.rg_tree_selected;
    let mut offset = app.rg_tree_offset;
    let is_leaf = selected > 0 && app.tree.get(selected).map(|t| t.kind == TreeKind::Leaf).unwrap_or(false);
    let rest = super::schema::render_tree(frame, app, area, tw, selected, &mut offset, selected > 0);
    app.rg_tree_offset = offset;
    if rest.width == 0 {
        return;
    }
    let nrg = app.num_row_groups();
    let rg_idx = app.rg_index.min(nrg.saturating_sub(1));

    let [gauge_area, below] = Layout::vertical([Constraint::Length(3), Constraint::Min(0)]).areas(rest);
    draw_gauge(frame, rg_idx, nrg, gauge_area);
    if nrg == 0 {
        return;
    }
    if is_leaf {
        draw_column(frame, app, rg_idx, selected, below);
    } else {
        draw_overview(frame, app, rg_idx, below);
    }
}

fn draw_gauge(frame: &mut Frame, rg_idx: usize, nrg: usize, area: Rect) {
    let title = Span::styled(format!(" Row Group: {} / {} ", rg_idx + 1, nrg), Style::default().add_modifier(Modifier::BOLD));
    let block = Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Gray)).title(title);
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let ratio = if nrg == 0 { 0.0 } else { (rg_idx + 1) as f64 / nrg as f64 };
    let filled = (inner.width as f64 * ratio).round() as u16;
    let buf = frame.buffer_mut();
    for y in inner.top()..inner.bottom() {
        for x in inner.left()..inner.left() + filled.min(inner.width) {
            buf[(x, y)].set_symbol(symbols::block::FULL).set_style(Style::default().fg(Color::Blue));
        }
    }
}

struct RgStats {
    rows: i64,
    comp: i64,
    unc: i64,
}

fn rg_stats(rg: &RowGroup) -> RgStats {
    let mut comp = 0;
    let mut unc = 0;
    for cc in &rg.columns {
        if let Some(m) = &cc.meta_data {
            comp += m.total_compressed_size;
            unc += m.total_uncompressed_size;
        }
    }
    RgStats { rows: rg.num_rows, comp, unc }
}

fn stat_box(frame: &mut Frame, area: Rect, title: &str, value: &str, cur: &str, total: &str) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Blue))
        .title(Span::styled(title.to_string(), Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)))
        .title_bottom(
            Line::from(vec![
                Span::styled(cur.to_string(), Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD)),
                Span::styled(" / ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                Span::styled(total.to_string(), Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD)),
            ])
            .centered(),
        );
    let inner = block.inner(area);
    frame.render_widget(block, area);
    let p = Paragraph::new(Line::from(Span::styled(value.to_string(), super::bold_yellow())))
        .alignment(Alignment::Center);
    frame.render_widget(p, inner);
}

fn draw_overview(frame: &mut Frame, app: &App, rg_idx: usize, area: Rect) {
    let md = app.metadata();
    let rg = &md.row_groups[rg_idx];
    let st = rg_stats(rg);
    let all: Vec<RgStats> = md.row_groups.iter().map(rg_stats).collect();
    let total_rows: i64 = all.iter().map(|s| s.rows).sum();
    let total_comp: i64 = all.iter().map(|s| s.comp).sum();
    let total_unc: i64 = all.iter().map(|s| s.unc).sum();

    let [boxes_area, charts_area] = Layout::vertical([Constraint::Length(3), Constraint::Min(0)]).areas(area);
    let box_rects = Layout::horizontal([Constraint::Fill(1); 4]).split(boxes_area);
    stat_box(frame, box_rects[0], "Rows", &thousands(st.rows), &thousands(st.rows), &thousands(total_rows));
    stat_box(frame, box_rects[1], "Compressed", &fmt_bytes_kib(st.comp), &fmt_bytes_kib(st.comp), &fmt_bytes_kib(total_comp));
    stat_box(frame, box_rects[2], "Uncompressed", &fmt_bytes_kib(st.unc), &fmt_bytes_kib(st.unc), &fmt_bytes_kib(total_unc));
    stat_box(
        frame,
        box_rects[3],
        "Ratio",
        &format!("{:.2}", ratio(st.unc, st.comp)),
        &format!("{:.2}", ratio(st.unc, st.comp)),
        &format!("{:.2}", ratio(total_unc, total_comp)),
    );

    // charts occupy the left half
    let [chart_cols, _] = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)]).areas(charts_area);
    let [c1, c2] = Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)]).areas(chart_cols);

    let n = all.len();
    let x_bounds = [0.0, (n + 1) as f64];
    let x_labels: Vec<Span> = (1..=n).map(|i| Span::raw(i.to_string())).collect();

    // chart 1: compressed vs uncompressed
    let comp_pts: Vec<(f64, f64)> = all.iter().enumerate().map(|(i, s)| ((i + 1) as f64, s.comp as f64)).collect();
    let unc_pts: Vec<(f64, f64)> = all.iter().enumerate().map(|(i, s)| ((i + 1) as f64, s.unc as f64)).collect();
    let max_v = all.iter().map(|s| s.comp.max(s.unc)).max().unwrap_or(0) as f64;
    let y_hi = max_v * 1.5;
    let y_labels: Vec<Span> = (0..4).map(|i| Span::raw(fmt_axis_bytes(y_hi * i as f64 / 4.0))).collect();
    let datasets = vec![
        Dataset::default()
            .marker(symbols::Marker::Dot)
            .graph_type(GraphType::Scatter)
            .style(Style::default().fg(Color::Blue))
            .data(&comp_pts),
        Dataset::default()
            .marker(symbols::Marker::Dot)
            .graph_type(GraphType::Scatter)
            .style(Style::default().fg(Color::Red))
            .data(&unc_pts),
    ];
    let title1 = Line::from(vec![
        Span::styled("Compressed", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
        Span::raw(" vs "),
        Span::styled("Uncompressed", Style::default().fg(Color::LightRed).add_modifier(Modifier::BOLD)),
        Span::raw(" (B)"),
    ])
    .centered();
    let block1 = Block::default()
        .title(title1)
        .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))));
    let chart1 = Chart::new(datasets)
        .block(block1)
        .x_axis(Axis::default().bounds(x_bounds).labels(x_labels.clone()).style(Style::default().fg(Color::White)))
        .y_axis(Axis::default().bounds([0.0, y_hi]).labels(y_labels).style(Style::default().fg(Color::White)));
    frame.render_widget(chart1, c1);

    // chart 2: compression ratio
    let ratio_pts: Vec<(f64, f64)> =
        all.iter().enumerate().map(|(i, s)| ((i + 1) as f64, ratio(s.unc, s.comp))).collect();
    let max_r = ratio_pts.iter().map(|p| p.1).fold(0.0f64, f64::max);
    let lo = 1.0;
    let hi = max_r * 1.1;
    let r_labels: Vec<Span> = (0..4).map(|i| Span::raw(format!("{:.1}x", lo + (hi - lo) * i as f64 / 4.0))).collect();
    let datasets2 = vec![Dataset::default()
        .marker(symbols::Marker::Dot)
        .graph_type(GraphType::Scatter)
        .style(Style::default().fg(Color::Yellow))
        .data(&ratio_pts)];
    let block2 = Block::default()
        .title(Span::styled("Compression Ratio", Style::default().fg(Color::Yellow)))
        .title_bottom(Line::from(Span::styled("Row Group", Style::default().fg(Color::DarkGray))));
    let chart2 = Chart::new(datasets2)
        .block(block2)
        .x_axis(Axis::default().bounds(x_bounds).labels(x_labels).style(Style::default().fg(Color::White)))
        .y_axis(Axis::default().bounds([lo, hi]).labels(r_labels).style(Style::default().fg(Color::White)));
    frame.render_widget(chart2, c2);
}

/// Format a statistics value for the row-group column detail panel.
fn fmt_stat_detail(pt: PhysicalType, bytes: Option<&Vec<u8>>) -> String {
    let Some(b) = bytes else { return "N/A".to_string() };
    match pt {
        PhysicalType::Boolean => {
            if b.first().copied().unwrap_or(0) != 0 {
                "true".to_string()
            } else {
                "false".to_string()
            }
        }
        PhysicalType::Int32 => {
            if b.len() >= 4 {
                format!("{}", i32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            } else {
                "N/A".to_string()
            }
        }
        PhysicalType::Int64 => {
            if b.len() >= 8 {
                let mut a = [0u8; 8];
                a.copy_from_slice(&b[..8]);
                format!("{}", i64::from_le_bytes(a))
            } else {
                "N/A".to_string()
            }
        }
        PhysicalType::Int96 => "N/A".to_string(),
        PhysicalType::Float => {
            if b.len() >= 4 {
                format!("{}", f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            } else {
                "N/A".to_string()
            }
        }
        PhysicalType::Double => {
            if b.len() >= 8 {
                let mut a = [0u8; 8];
                a.copy_from_slice(&b[..8]);
                format!("{}", f64::from_le_bytes(a))
            } else {
                "N/A".to_string()
            }
        }
        PhysicalType::ByteArray | PhysicalType::FixedLenByteArray => match std::str::from_utf8(b) {
            Ok(s) => s.to_string(),
            Err(_) => "N/A".to_string(),
        },
    }
}

fn indicator(frame: &mut Frame, area: Rect, title: &str, ok: bool) {
    let color = if ok { Color::Green } else { Color::Red };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(color))
        .title(Span::styled(title.to_string(), Style::default().add_modifier(Modifier::BOLD)));
    let inner = block.inner(area);
    frame.render_widget(block, area);
    let sym = if ok { "✓" } else { "✗" };
    let p = Paragraph::new(Line::from(Span::styled(sym, Style::default().fg(color).add_modifier(Modifier::BOLD))))
        .alignment(Alignment::Center);
    frame.render_widget(p, inner);
}

fn kv_table<'a>(rows: Vec<(String, String)>, label_style: Style) -> Table<'a> {
    let trows: Vec<Row> = rows
        .into_iter()
        .map(|(k, v)| {
            Row::new(vec![Cell::from(k).style(label_style), Cell::from(v).style(Style::default().fg(Color::White))])
        })
        .collect();
    Table::new(trows, [Constraint::Length(18), Constraint::Min(0)]).column_spacing(1)
}

fn draw_column(frame: &mut Frame, app: &App, rg_idx: usize, selected: usize, area: Rect) {
    let item = &app.tree[selected];
    let li = item.leaf_index.unwrap_or(0);
    let md = app.metadata();
    let rg = &md.row_groups[rg_idx];
    let cc = rg.columns.get(li);
    let cm = cc.and_then(|c| c.meta_data.as_ref());
    let leaf = app.file.schema.leaves.get(li);
    let col_name = leaf.map(|l| l.path.join(".")).unwrap_or_default();

    let [title_area, ind_area, lower] =
        Layout::vertical([Constraint::Length(1), Constraint::Length(3), Constraint::Min(0)]).areas(area);
    // column title line
    let title = Line::from(vec![
        Span::raw(" Column: "),
        Span::styled(format!("\"{}\"", col_name), super::bold_yellow()),
        Span::raw(" "),
    ])
    .centered();
    let tblock = Block::default().borders(Borders::TOP).border_style(Style::default().fg(Color::Blue)).title(title);
    frame.render_widget(tblock, title_area);

    // indicators
    let has_stats = cm.map(|m| m.statistics.is_some()).unwrap_or(false);
    let has_dict = cm.map(|m| m.dictionary_page_offset.is_some()).unwrap_or(false);
    let has_bloom = cm.map(|m| m.bloom_filter_offset.is_some()).unwrap_or(false);
    let has_page_stats = cm.map(|m| m.encoding_stats.is_some()).unwrap_or(false);
    let ind_rects = Layout::horizontal([Constraint::Fill(1); 4]).split(ind_area);
    indicator(frame, ind_rects[0], "Statistics", has_stats);
    indicator(frame, ind_rects[1], "Dict Page", has_dict);
    indicator(frame, ind_rects[2], "Bloom Filter", has_bloom);
    indicator(frame, ind_rects[3], "Page Stats", has_page_stats);

    let [left, right] = Layout::horizontal([Constraint::Fill(3), Constraint::Fill(5)]).areas(lower);
    let [meta_area, stats_area, _] =
        Layout::vertical([Constraint::Length(7), Constraint::Length(6), Constraint::Min(0)]).areas(left);

    // metadata block
    let (file_offset, comp, unc, codec) = match cm {
        Some(m) => {
            let off = m.dictionary_page_offset.filter(|&d| d > 0 && d < m.data_page_offset).unwrap_or(m.data_page_offset);
            (off, m.total_compressed_size, m.total_uncompressed_size, m.codec.display())
        }
        None => (0, 0, 0, String::new()),
    };
    let meta_rows = vec![
        ("File Offset (B)".to_string(), thousands(file_offset)),
        ("Compressed Size".to_string(), fmt_bytes_kib(comp)),
        ("Uncompressed Size".to_string(), fmt_bytes_kib(unc)),
        ("Compression Ratio".to_string(), format!("{:.2}x", ratio(unc, comp))),
        ("Compression Type".to_string(), codec),
    ];
    let mblock = Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Blue)).title("Metadata");
    let minner = mblock.inner(meta_area);
    frame.render_widget(mblock, meta_area);
    frame.render_widget(kv_table(meta_rows, Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)), minner);

    // statistics block
    let pt = leaf.map(|l| l.physical_type).unwrap_or(PhysicalType::Boolean);
    let (min_s, max_s, nulls, distinct) = match cm.and_then(|m| m.statistics.as_ref()) {
        Some(s) => (
            fmt_stat_detail(pt, s.min_bytes()),
            fmt_stat_detail(pt, s.max_bytes()),
            s.null_count.map(thousands).unwrap_or_else(|| "0".to_string()),
            s.distinct_count.map(thousands).unwrap_or_else(|| "N/A".to_string()),
        ),
        None => ("N/A".to_string(), "N/A".to_string(), "0".to_string(), "N/A".to_string()),
    };
    let stat_rows = vec![
        ("Min".to_string(), min_s),
