/// Replicates ratatui's chart layout to find the graph area (x & y labels present, no legend).
fn graph_area(inner: Rect, y_label_max_w: u16, first_x_label_w: u16, has_x_labels: bool) -> Option<Rect> {
    if inner.height == 0 || inner.width == 0 {
        return None;
    }
    let mut x = inner.left();
    let mut y = inner.bottom() - 1;
    if has_x_labels && y > inner.top() {
        y -= 1;
    }
    let mut max_w = y_label_max_w;
    if has_x_labels {
        max_w = max_w.max(first_x_label_w.saturating_sub(1));
    }
    max_w = max_w.min(inner.width / 3);
    x += max_w;
    if has_x_labels && y > inner.top() {
        y -= 1;
    }
    if x + 1 < inner.right() {
        x += 1;
    }
    let w = inner.right().saturating_sub(x);
    let h = y.saturating_sub(inner.top()) + 1;
    if w == 0 || h == 0 {
        return None;
    }
    Some(Rect::new(x, inner.top(), w, h))
}

/// Adjust points so that rounding to a cell gives the same result as truncation (ratatui 0.29 behaviour).
fn adjust_points(points: &[(f64, f64)], xb: [f64; 2], yb: [f64; 2], graph: Option<Rect>) -> Vec<(f64, f64)> {
    let Some(g) = graph else { return vec![] };
    let (left, right) = (xb[0], xb[1]);
    let (bottom, top) = (yb[0], yb[1]);
    let width = (right - left).abs();
    let height = (top - bottom).abs();
    if width == 0.0 || height == 0.0 {
        return vec![];
    }
    let rw = g.width as f64;
    let rh = g.height as f64;
    let mut out = Vec::new();
    for &(x, y) in points {
        if x < left || x > right || y < bottom || y > top {
            continue;
        }
        let xc = ((x - left) * (rw - 1.0) / width) as usize;
        let yc = ((top - y) * (rh - 1.0) / height) as usize;
        let xa = if rw > 1.0 { left + xc as f64 * width / (rw - 1.0) } else { left };
        let ya = if rh > 1.0 { top - yc as f64 * height / (rh - 1.0) } else { top };
        out.push((xa, ya));
    }
    out
}
'''
