//! Minimal reader for the Arrow IPC schema stored in the `ARROW:schema` key-value metadata.
//! Only extracts timestamp time zones (used to emulate polars' validation).

fn b64_decode(s: &str) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    let mut buf: u32 = 0;
    let mut bits = 0;
    for c in s.bytes() {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
