"""Minimal Parquet writer (PLAIN encoding, uncompressed, data page v1)."""
import struct

# ---- thrift compact writer
class W:
    def __init__(self): self.b=bytearray(); self.last=[0]; self.cur=0
    def varint(self, n):
        while True:
            x=n&0x7f; n>>=7
            if n: self.b.append(x|0x80)
            else: self.b.append(x); break
    def zig(self, n): self.varint((n<<1) ^ (n>>63))
