        d=fid-self.cur
        if 0<d<16: self.b.append((d<<4)|t)
        else:
            self.b.append(t); self.zig(fid)  # i16 zigzag
        self.cur=fid
    def i32(self, fid, v): self.field(fid,5); self.zig(v)
    def i64(self, fid, v): self.field(fid,6); self.zig(v)
    def boolf(self, fid, v): self.field(fid, 1 if v else 2)
    def binary(self, fid, v):
        self.field(fid,8); self.varint(len(v)); self.b+=v
    def string(self, fid, s): self.binary(fid, s.encode())
    def struct_begin(self, fid):
        self.field(fid,12); self.last.append(self.cur); self.cur=0
    def struct_end(self):
        self.b.append(0); self.cur=self.last.pop()
    def list_begin(self, fid, et, n):
        self.field(fid,9)
        if n<15: self.b.append((n<<4)|et)
        else: self.b.append(0xF0|et); self.varint(n)
    # inside list of structs: struct with no field header
    def elem_struct_begin(self): self.last.append(self.cur); self.cur=0
    def elem_i32(self, v): self.zig(v)
    def elem_string(self, s): b=s.encode(); self.varint(len(b)); self.b+=b

TYPES={'BOOLEAN':0,'INT32':1,'INT64':2,'INT96':3,'FLOAT':4,'DOUBLE':5,'BYTE_ARRAY':6,'FIXED_LEN_BYTE_ARRAY':7}
CONV={'UTF8':0,'MAP':1,'MAP_KEY_VALUE':2,'LIST':3,'ENUM':4,'DECIMAL':5,'DATE':6,'TIME_MILLIS':7,'TIME_MICROS':8,'TIMESTAMP_MILLIS':9,'TIMESTAMP_MICROS':10,'UINT_8':11,'UINT_16':12,'UINT_32':13,'UINT_64':14,'INT_8':15,'INT_16':16,'INT_32':17,'INT_64':18,'JSON':19,'BSON':20,'INTERVAL':21}

def write_logical(w, lt):
    # lt: dict like {'kind':'TIMESTAMP','utc':True,'unit':'MILLIS'}
    w.struct_begin(10)
    k=lt['kind']
    ids={'STRING':1,'MAP':2,'LIST':3,'ENUM':4,'DECIMAL':5,'DATE':6,'TIME':7,'TIMESTAMP':8,'INTEGER':10,'UNKNOWN':11,'JSON':12,'BSON':13,'UUID':14,'FLOAT16':15}
