        for v in values: out+=struct.pack('<f', v)
    elif ptype=='DOUBLE':
        for v in values: out+=struct.pack('<d', v)
    elif ptype=='BYTE_ARRAY':
        for v in values:
            if isinstance(v,str): v=v.encode()
            out+=struct.pack('<I', len(v))+v
    elif ptype=='FIXED_LEN_BYTE_ARRAY':
        for v in values:
            assert len(v)==type_length
            out+=v
    return bytes(out)

def stat_bytes(ptype, v, type_length=0):
    return plain_encode(ptype, [v], type_length) if ptype!='BYTE_ARRAY' else (v.encode() if isinstance(v,str) else v)

class Column:
    def __init__(self, name, ptype, values, optional=True, converted=None, logical=None, type_length=None, scale=None, precision=None, stats=True):
        self.name=name; self.ptype=ptype; self.values=values; self.optional=optional
        self.converted=converted; self.logical=logical; self.type_length=type_length
        self.scale=scale; self.precision=precision; self.stats=stats

def write_file(path, columns, row_groups, created_by='pqwrite test', codec_name='UNCOMPRESSED'):
    """columns: list of Column with values as list of lists (one per row group)"""
    out=bytearray(b'PAR1')
    rg_meta=[]
    for rg in range(row_groups):
        cols_meta=[]
        nrows=len(columns[0].values[rg])
        for col in columns:
            vals=col.values[rg]
            start=len(out)
            nonnull=[v for v in vals if v is not None]
            body=bytearray()
            if col.optional:
                body+=rle_levels([0 if v is None else 1 for v in vals])
            body+=plain_encode(col.ptype, nonnull, col.type_length or 0)
            # page header
            w=W()
            w.i32(1,0); w.i32(2,len(body)); w.i32(3,len(body))
            w.struct_begin(5); w.i32(1,len(vals)); w.i32(2,0); w.i32(3,3); w.i32(4,3); w.struct_end()
            w.b.append(0)
            out+=w.b; out+=body
            size=len(out)-start
            # column metadata
            cm=W()
            cm.i32(1, TYPES[col.ptype])
            cm.list_begin(2,5,2); cm.elem_i32(0); cm.elem_i32(3)
            cm.list_begin(3,8,1); cm.elem_string(col.name)
            cm.i32(4,0); cm.i64(5,len(vals)); cm.i64(6,size); cm.i64(7,size); cm.i64(9,start)
            if col.stats and nonnull:
                mn=min(nonnull); mx=max(nonnull)
                cm.struct_begin(12)
                cm.i64(3, len(vals)-len(nonnull))
                cm.binary(5, stat_bytes(col.ptype, mx, col.type_length or 0))
                cm.binary(6, stat_bytes(col.ptype, mn, col.type_length or 0))
                cm.struct_end()
            cm.b.append(0)
            cols_meta.append((start, cm.b, size))
        rg_meta.append((cols_meta, nrows))
    # footer
    f=W()
    f.i32(1,1)
    f.list_begin(2,12,len(columns)+1)
    # root
    f.elem_struct_begin(); f.string(4,'schema'); f.i32(5,len(columns)); f.struct_end()
    for col in columns:
        f.elem_struct_begin()
        f.i32(1,TYPES[col.ptype])
        if col.type_length is not None: f.i32(2,col.type_length)
        f.i32(3, 1 if col.optional else 0)
        f.string(4,col.name)
        if col.converted is not None: f.i32(6,CONV[col.converted])
        if col.scale is not None: f.i32(7,col.scale)
        if col.precision is not None: f.i32(8,col.precision)
        if col.logical is not None: write_logical(f, col.logical)
        f.struct_end()
    total_rows=sum(n for _,n in rg_meta)
    f.i64(3,total_rows)
    f.list_begin(4,12,len(rg_meta))
    for cols_meta,nrows in rg_meta:
        f.elem_struct_begin()
        f.list_begin(1,12,len(cols_meta))
        total=0
        for start,cmb,size in cols_meta:
            f.elem_struct_begin()
            f.i64(2,start)
            f.field(3,12); f.last.append(f.cur); f.cur=0; f.b+=cmb; f.cur=f.last.pop()
            f.struct_end()
            total+=size
        f.i64(2,total); f.i64(3,nrows)
        f.struct_end()
    if created_by is not None: f.string(6,created_by)
    f.b.append(0)
    out+=f.b
    out+=struct.pack('<I', len(f.b))+b'PAR1'
    open(path,'wb').write(out)
