/// Map control characters to private-use placeholders so that they survive ratatui's
/// rendering (which filters control characters). They are restored to the raw control
/// characters right before the buffer is flushed (see `restore_controls`).
pub fn protect(s: &str) -> String {
    if !s.chars().any(|c| c.is_control()) {
        return s.to_string();
    }
    s.chars()
        .map(|c| if c.is_control() && (c as u32) < 0xA0 { char::from_u32(0xE000 + c as u32).unwrap_or(c) } else { c })
        .collect()
}

/// Remove control characters (used for data cells).
pub fn strip_controls(s: &str) -> String {
    if !s.chars().any(|c| c.is_control()) {
        return s.to_string();
    }
    s.chars().filter(|c| !c.is_control()).collect()
}

/// Restore placeholder characters in the buffer to raw control characters.
pub fn restore_controls(buf: &mut ratatui::buffer::Buffer) {
    let area = buf.area;
    for y in area.top()..area.bottom() {
        for x in area.left()..area.right() {
            let cell = &mut buf[(x, y)];
            let sym = cell.symbol();
            let mut chars = sym.chars();
            if let (Some(c), None) = (chars.next(), chars.next()) {
